// 02-01: primitive-types (50 exercises)
writeLesson("02-data-types", 0, "primitive-types", [
  { id: "02-01-01", title: "String banalo profile se", starterCode: '// Name, city aur country variables banao (sab strings)\n// Return as object: { name, city, country }\n', solution: 'const name = "Hariom"\nconst city = "Jaipur"\nconst country = "India"\nreturn { name, city, country }', tests: [{ input: [], expected: { name: "Hariom", city: "Jaipur", country: "India" } }], hints: ["const ya let se string variables declare karo", "Double quotes ya single quotes use karo"] },
  { id: "02-01-02", title: "Number types explore karo", starterCode: '// Integer, float, negative aur zero declare karo\n// Return as array: [integer, float, negative, zero]\n', solution: 'const integer = 42\nconst float = 3.14\nconst negative = -10\nconst zero = 0\nreturn [integer, float, negative, zero]', tests: [{ input: [], expected: [42, 3.14, -10, 0] }], hints: ["Integer bina decimal ke, float decimal ke saath", "Negative number minus sign se"] },
  { id: "02-01-03", title: "Boolean values banao", starterCode: '// isActive = true, isDeleted = false, hasPermission = true\n// Return object with all three\n', solution: 'const isActive = true\nconst isDeleted = false\nconst hasPermission = true\nreturn { isActive, isDeleted, hasPermission }', tests: [{ input: [], expected: { isActive: true, isDeleted: false, hasPermission: true } }], hints: ["true aur false sirf do boolean values hain", "Comparison operators boolean return karte hain"] },
  { id: "02-01-04", title: "undefined vs null check", starterCode: 'const undefinedVar = undefined\nconst nullVar = null\nreturn {\n  undefinedType: typeof undefinedVar,\n  nullType: typeof nullVar,\n  undefinedValue: undefinedVar,\n  nullValue: nullVar\n}\n', solution: 'const undefinedVar = undefined\nconst nullVar = null\nreturn {\n  undefinedType: typeof undefinedVar,\n  nullType: typeof nullVar,\n  undefinedValue: undefinedVar,\n  nullValue: nullVar\n}', tests: [{ input: [], expected: { undefinedType: "undefined", nullType: "object", undefinedValue: undefined, nullValue: null } }], hints: ["typeof undefined returns 'undefined'", "typeof null returns 'object' (JS bug)"] },
  { id: "02-01-05", title: "BigInt declare karo", starterCode: '// Do bade numbers declare karo BigInt se\n// 9007199254740993n aur 12345678901234567890n\n// Return sum as string\n', solution: 'const big1 = 9007199254740993n\nconst big2 = 12345678901234567890n\nreturn (big1 + big2).toString()', tests: [{ input: [], expected: "21342878155955452883" }], hints: ["n suffix se BigInt banta hai", "BigInt sirf BigInt se add hota hai", "toString se string mein convert karo for comparison"] },
  { id: "02-01-06", title: "Symbol unique identifier", starterCode: '// Do symbols banao — dono unique hone chahiye\nconst s1 = Symbol("id")\nconst s2 = Symbol("id")\nreturn {\n  areEqual: s1 === s2,\n  s1Description: s1.description,\n  s2Description: s2.description\n}\n', solution: 'const s1 = Symbol("id")\nconst s2 = Symbol("id")\nreturn {\n  areEqual: s1 === s2,\n  s1Description: s1.description,\n  s2Description: s2.description\n}', tests: [{ input: [], expected: { areEqual: false, s1Description: "id", s2Description: "id" } }], hints: ["Symbol hamesha unique hota hai", "description property se description milta hai"] },
  { id: "02-01-07", title: "typeof operator use karo", starterCode: 'const values = [42, "hello", true, null, undefined, Symbol("x"), 42n]\nreturn values.map(v => typeof v)\n', solution: 'const values = [42, "hello", true, null, undefined, Symbol("x"), 42n]\nreturn values.map(v => typeof v)', tests: [{ input: [], expected: ["number", "string", "boolean", "object", "undefined", "symbol", "bigint"] }], hints: ["typeof null 'object' return karta hai", "typeof Symbol 'symbol' return karta hai"] },
  { id: "02-01-08", title: "NaN detect karo", starterCode: 'function isActualNaN(val) {\n  // TODO: Object.is use karo\n}\n', solution: 'function isActualNaN(val) {\n  return Object.is(val, NaN)\n}', tests: [{ input: [NaN], expected: true }, { input: [42], expected: false }, { input: ["hello"], expected: false }], hints: ["Object.is(NaN, NaN) true deta hai", "typeof NaN 'number' hai"] },
  { id: "02-01-09", title: "Infinity aur -Infinity", starterCode: 'const inf = Infinity\nconst negInf = -Infinity\nreturn {\n  infGreaterThanMillion: inf > 1000000,\n  negInfLessThan: negInf < -999999,\n  isFinite: isFinite(inf)\n}\n', solution: 'const inf = Infinity\nconst negInf = -Infinity\nreturn {\n  infGreaterThanMillion: inf > 1000000,\n  negInfLessThan: negInf < -999999,\n  isFinite: isFinite(inf)\n}', tests: [{ input: [], expected: { infGreaterThanMillion: true, negInfLessThan: true, isFinite: false } }], hints: ["Infinity koi bhi number se bada hota hai", "isFinite() check karta hai finite hai ya nahi"] },
  { id: "02-01-10", title: "Primitive immutability verify karo", starterCode: 'const name = "hariom"\nconst upper = name.toUpperCase()\nreturn {\n  original: name,\n  uppercased: upper,\n  isChanged: name !== upper\n}\n', solution: 'const name = "hariom"\nconst upper = name.toUpperCase()\nreturn {\n  original: name,\n  uppercased: upper,\n  isChanged: name !== upper\n}', tests: [{ input: [], expected: { original: "hariom", uppercased: "HARIOM", isChanged: true } }], hints: ["Primitive values mutate nahi hote", "toUpperCase naya string return karta hai"] },
  { id: "02-01-11", title: "Template literal se dynamic string", starterCode: 'const user = { name: "Rahul", age: 25, city: "Mumbai" }\n// Template literal use karke return karo:\n// "Rahul is 25 years old and lives in Mumbai"\n', solution: 'const user = { name: "Rahul", age: 25, city: "Mumbai" }\nreturn `${user.name} is ${user.age} years old and lives in ${user.city}`', tests: [{ input: [], expected: "Rahul is 25 years old and lives in Mumbai" }], hints: ["Backtick ` use karo", "${variable} se value inject hoti hai"] },
  { id: "02-01-12", title: "String length aur access", starterCode: 'const str = "JavaScript"\nreturn {\n  first: str[0],\n  last: str[str.length - 1],\n  length: str.length\n}\n', solution: 'const str = "JavaScript"\nreturn {\n  first: str[0],\n  last: str[str.length - 1],\n  length: str.length\n}', tests: [{ input: [], expected: { first: "J", last: "t", length: 10 } }], hints: ["str[0] se pehla character milta hai", "str.length se length milta hai"] },
  { id: "02-01-13", title: "Number precision problem", starterCode: 'const result = 0.1 + 0.2\nreturn {\n  result: result,\n  isExactlyPointThree: result === 0.3,\n  workaround: Math.round(result * 100) / 100\n}', solution: 'const result = 0.1 + 0.2\nreturn {\n  result: result,\n  isExactlyPointThree: result === 0.3,\n  workaround: Math.round(result * 100) / 100\n}', tests: [{ input: [], expected: { result: 0.30000000000000004, isExactlyPointThree: false, workaround: 0.3 } }], hints: ["Floating point precision issue hai", "Math.round ya toFixed use karo workaround ke liye"] },
  { id: "02-01-14", title: "Type coercion examples", starterCode: 'return {\n  strPlusNum: "5" + 3,\n  strMinusNum: "5" - 3,\n  boolPlusNum: true + 1,\n  nullPlusNum: null + 1,\n  emptyStrBool: Boolean("")\n}', solution: 'return {\n  strPlusNum: "5" + 3,\n  strMinusNum: "5" - 3,\n  boolPlusNum: true + 1,\n  nullPlusNum: null + 1,\n  emptyStrBool: Boolean("")\n}', tests: [{ input: [], expected: { strPlusNum: "53", strMinusNum: 2, boolPlusNum: 2, nullPlusNum: 1, emptyStrBool: false } }], hints: ["'+' operator string concat bhi karta hai", "true = 1, null = 0 numeric context mein"] },
  { id: "02-01-15", title: "let vs const reassignment", starterCode: 'let counter = 0\ncounter = counter + 1\ncounter += 1\nconst PI = 3.14\nreturn {\n  counter: counter,\n  pi: PI\n}\n', solution: 'let counter = 0\ncounter = counter + 1\ncounter += 1\nconst PI = 3.14\nreturn {\n  counter: counter,\n  pi: PI\n}', tests: [{ input: [], expected: { counter: 2, pi: 3.14 } }], hints: ["let se reassign ho sakta hai", "const se reassign nahi ho sakta"] },
  { id: "02-01-16", title: "String to Number conversion methods", starterCode: 'const price = "199.99"\nreturn {\n  numFunc: Number(price),\n  parseFloat: parseFloat(price),\n  unaryPlus: +price,\n  allEqual: Number(price) === parseFloat(price) && parseFloat(price) === +price\n}\n', solution: 'const price = "199.99"\nreturn {\n  numFunc: Number(price),\n  parseFloat: parseFloat(price),\n  unaryPlus: +price,\n  allEqual: Number(price) === parseFloat(price) && parseFloat(price) === +price\n}', tests: [{ input: [], expected: { numFunc: 199.99, parseFloat: 199.99, unaryPlus: 199.99, allEqual: true } }], hints: ["Number(), parseFloat(), + sab same result dete hain", "parseInt sirf integer part deta hai"] },
  { id: "02-01-17", title: "Nullish vs falsy values", starterCode: 'const falsyValues = [false, 0, "", null, undefined, NaN]\nreturn falsyValues.map(v => ({\n  value: v,\n  isFalsy: !Boolean(v),\n  type: typeof v\n}))\n', solution: 'const falsyValues = [false, 0, "", null, undefined, NaN]\nreturn falsyValues.map(v => ({\n  value: v,\n  isFalsy: !Boolean(v),\n  type: typeof v\n}))', tests: [{ input: [], expected: [{ value: false, isFalsy: true, type: "boolean" }, { value: 0, isFalsy: true, type: "number" }, { value: "", isFalsy: true, type: "string" }, { value: null, isFalsy: true, type: "object" }, { value: undefined, isFalsy: true, type: "undefined" }, { value: NaN, isFalsy: true, type: "number" }] }], hints: ["false, 0, '', null, undefined, NaN sab falsy hain", "Sirf truthy values hain: true, non-zero numbers, non-empty strings, objects"] },
  { id: "02-01-18", title: "Variable naming conventions", starterCode: 'const camelCase = "userAge"\nconst PascalCase = "UserProfile"\nconst snake_case = "user_name"\nconst SCREAMING = "MAX_SIZE"\nreturn { camelCase, PascalCase, snake_case, SCREAMING }\n', solution: 'const camelCase = "userAge"\nconst PascalCase = "UserProfile"\nconst snake_case = "user_name"\nconst SCREAMING = "MAX_SIZE"\nreturn { camelCase, PascalCase, snake_case, SCREAMING }', tests: [{ input: [], expected: { camelCase: "userAge", PascalCase: "UserProfile", snake_case: "user_name", SCREAMING: "MAX_SIZE" } }], hints: ["camelCase: variables ke liye", "PascalCase: classes/components ke liye", "SCREAMING_SNAKE: constants ke liye"] },
  { id: "02-01-19", title: "Destructuring assignment", starterCode: 'const user = { name: "Amit", age: 25, city: "Delhi" }\nconst { name, age, city } = user\nreturn { name, age, city }\n', solution: 'const user = { name: "Amit", age: 25, city: "Delhi" }\nconst { name, age, city } = user\nreturn { name, age, city }', tests: [{ input: [], expected: { name: "Amit", age: 25, city: "Delhi" } }], hints: ["const { prop } = obj se destructuring hoti hai", "Variable names property names se match hone chahiye"] },
  { id: "02-01-20", title: "Array destructuring", starterCode: 'const colors = ["red", "green", "blue", "yellow"]\nconst [first, second, ...rest] = colors\nreturn { first, second, rest }\n', solution: 'const colors = ["red", "green", "blue", "yellow"]\nconst [first, second, ...rest] = colors\nreturn { first, second, rest }', tests: [{ input: [], expected: { first: "red", second: "green", rest: ["blue", "yellow"] } }], hints: ["[a, b] = arr se pehle do elements milte hain", "...rest se baaki sab collect hota hai"] },
  { id: "02-01-21", title: "String comparison", starterCode: 'return {\n  appleVsBanana: "apple" < "banana",\n  abcVsAbc: "abc" === "abc",\n  caseSensitive: "Apple" !== "apple",\n  lengthCompare: "hi".length < "hello".length\n}\n', solution: 'return {\n  appleVsBanana: "apple" < "banana",\n  abcVsAbc: "abc" === "abc",\n  caseSensitive: "Apple" !== "apple",\n  lengthCompare: "hi".length < "hello".length\n}', tests: [{ input: [], expected: { appleVsBanana: true, abcVsAbc: true, caseSensitive: true, lengthCompare: true } }], hints: ["Strings alphabetical order mein compare hoti hain", "Case-sensitive comparison hota hai"] },
  { id: "02-01-22", title: "Number methods practical", starterCode: 'const num = 123.456\nreturn {\n  twoDecimals: parseFloat(num.toFixed(2)),\n  fourPrecision: parseFloat(num.toPrecision(4)),\n  truncated: parseInt(num)\n}\n', solution: 'const num = 123.456\nreturn {\n  twoDecimals: parseFloat(num.toFixed(2)),\n  fourPrecision: parseFloat(num.toPrecision(4)),\n  truncated: parseInt(num)\n}', tests: [{ input: [], expected: { twoDecimals: 123.46, fourPrecision: 123.5, truncated: 123 } }], hints: ["toFixed(n) se n decimal places milte hain", "toPrecision(n) se n significant digits milte hain"] },
  { id: "02-01-23", title: "String reverse without methods", starterCode: 'function reverseString(str) {\n  // TODO: use split, reverse, join\n}\n', solution: 'function reverseString(str) {\n  return str.split("").reverse().join("")\n}', tests: [{ input: ["hello"], expected: "olleh" }, { input: ["JavaScript"], expected: "tpircSavaJ" }], hints: ["split('') se array banta hai", "reverse() array reverse karta hai", "join('') se string banti hai"] },
  { id: "02-01-24", title: "Coerce to boolean", starterCode: 'const values = [0, 1, "", "hello", null, undefined, NaN, [], {}]\nreturn values.map(v => !!v)\n', solution: 'const values = [0, 1, "", "hello", null, undefined, NaN, [], {}]\nreturn values.map(v => !!v)', tests: [{ input: [], expected: [false, true, false, true, false, false, false, true, true] }], hints: ["!!value se boolean milta hai", "Empty values false, objects/arrays true"] },
  { id: "02-01-25", title: "Optional chaining basic", starterCode: 'const user = { profile: { address: { city: "Mumbai" } } }\nconst city1 = user.profile?.address?.city\nconst zip = user.profile?.address?.zip\nconst phone = user.contact?.phone\nreturn { city1, zip, phone }\n', solution: 'const user = { profile: { address: { city: "Mumbai" } } }\nconst city1 = user.profile?.address?.city\nconst zip = user.profile?.address?.zip\nconst phone = user.contact?.phone\nreturn { city1, zip, phone }', tests: [{ input: [], expected: { city1: "Mumbai", zip: undefined, phone: undefined } }], hints: ["?. operator se safe access hota hai", "Agar path exist nahi karta to undefined return hota hai"] },
  { id: "02-01-26", title: "Nullish coalescing operator", starterCode: 'const username = null\nconst age = 0\nconst score = ""\nreturn {\n  name: username ?? "Guest",\n  userAge: age ?? 18,\n  userScore: score ?? 100\n}\n', solution: 'const username = null\nconst age = 0\nconst score = ""\nreturn {\n  name: username ?? "Guest",\n  userAge: age ?? 18,\n  userScore: score ?? 100\n}', tests: [{ input: [], expected: { name: "Guest", userAge: 0, userScore: "" } }], hints: ["?? sirf null/undefined ke liye default deta hai", "0 aur '' ko valid value maanta hai"] },
  { id: "02-01-27", title: "WeakMap basic usage", starterCode: 'const weakMap = new WeakMap()\nconst obj1 = { name: "user1" }\nconst obj2 = { name: "user2" }\nweakMap.set(obj1, "data1")\nweakMap.set(obj2, "data2")\nreturn {\n  data1: weakMap.get(obj1),\n  data2: weakMap.get(obj2),\n  hasObj1: weakMap.has(obj1)\n}\n', solution: 'const weakMap = new WeakMap()\nconst obj1 = { name: "user1" }\nconst obj2 = { name: "user2" }\nweakMap.set(obj1, "data1")\nweakMap.set(obj2, "data2")\nreturn {\n  data1: weakMap.get(obj1),\n  data2: weakMap.get(obj2),\n  hasObj1: weakMap.has(obj1)\n}', tests: [{ input: [], expected: { data1: "data1", data2: "data2", hasObj1: true } }], hints: ["WeakMap mein sirf objects keys ho sakte hain", "set(), get(), has() methods hain"] },
  { id: "02-01-28", title: "Map data structure", starterCode: 'const map = new Map()\nmap.set("name", "Hariom")\nmap.set(42, "answer")\nmap.set(true, "yes")\nreturn {\n  name: map.get("name"),\n  answer: map.get(42),\n  yes: map.get(true),\n  size: map.size\n}\n', solution: 'const map = new Map()\nmap.set("name", "Hariom")\nmap.set(42, "answer")\nmap.set(true, "yes")\nreturn {\n  name: map.get("name"),\n  answer: map.get(42),\n  yes: map.get(true),\n  size: map.size\n}', tests: [{ input: [], expected: { name: "Hariom", answer: "answer", yes: "yes", size: 3 } }], hints: ["Map kisi bhi type ki key accept karta hai", "size property se count milta hai"] },
  { id: "02-01-29", title: "Set for unique values", starterCode: 'const arr = [1, 2, 2, 3, 3, 3, 4]\nconst unique = new Set(arr)\nreturn {\n  uniqueArray: [...unique],\n  size: unique.size,\n  has3: unique.has(3)\n}\n', solution: 'const arr = [1, 2, 2, 3, 3, 3, 4]\nconst unique = new Set(arr)\nreturn {\n  uniqueArray: [...unique],\n  size: unique.size,\n  has3: unique.has(3)\n}', tests: [{ input: [], expected: { uniqueArray: [1, 2, 3, 4], size: 4, has3: true } }], hints: ["Set sirf unique values rakhta hai", "Spread operator se array mein convert karo"] },
  { id: "02-01-30", title: "Primitive vs Reference comparison", starterCode: 'const a = 5\nconst b = 5\nconst obj1 = { x: 1 }\nconst obj2 = { x: 1 }\nconst obj3 = obj1\nreturn {\n  primitivesEqual: a === b,\n  objectsEqual: obj1 === obj2,\n  referenceEqual: obj1 === obj3\n}\n', solution: 'const a = 5\nconst b = 5\nconst obj1 = { x: 1 }\nconst obj2 = { x: 1 }\nconst obj3 = obj1\nreturn {\n  primitivesEqual: a === b,\n  objectsEqual: obj1 === obj2,\n  referenceEqual: obj1 === obj3\n}', tests: [{ input: [], expected: { primitivesEqual: true, objectsEqual: false, referenceEqual: true } }], hints: ["Primitives value se compare hote hain", "Objects reference se compare hote hain"] },
  { id: "02-01-31", title: "String padding methods", starterCode: 'const num = "42"\nreturn {\n  padded: num.padStart(5, "0"),\n  rightPadded: "hi".padEnd(10, "!"),\n  both: "5".padStart(3, "0").padEnd(6, ".")\n}\n', solution: 'const num = "42"\nreturn {\n  padded: num.padStart(5, "0"),\n  rightPadded: "hi".padEnd(10, "!"),\n  both: "5".padStart(3, "0").padEnd(6, ".")\n}', tests: [{ input: [], expected: { padded: "00042", rightPadded: "hi!!!!!!!", both: "005..." } }], hints: ["padStart(length, char) se left se pad hota hai", "padEnd(length, char) se right se pad hota hai"] },
  { id: "02-01-32", title: "Number.isNaN vs isNaN", starterCode: 'return {\n  isNaNNaN: isNaN(NaN),\n  numberIsNaN: Number.isNaN(NaN),\n  isNaNString: isNaN("hello"),\n  numberIsNaNString: Number.isNaN("hello"),\n  isNaNUndefined: isNaN(undefined),\n  numberIsNaNUndefined: Number.isNaN(undefined)\n}\n', solution: 'return {\n  isNaNNaN: isNaN(NaN),\n  numberIsNaN: Number.isNaN(NaN),\n  isNaNString: isNaN("hello"),\n  numberIsNaNString: Number.isNaN("hello"),\n  isNaNUndefined: isNaN(undefined),\n  numberIsNaNUndefined: Number.isNaN(undefined)\n}', tests: [{ input: [], expected: { isNaNNaN: true, numberIsNaN: true, isNaNString: true, numberIsNaNString: false, isNaNUndefined: true, numberIsNaNUndefined: false } }], hints: ["isNaN pehle number mein convert karta hai", "Number.isNaN sirf NaN ko detect karta hai"] },
  { id: "02-01-33", title: "String repetition", starterCode: 'const dash = "-"\nreturn {\n  dashes: dash.repeat(5),\n  pattern: "ha".repeat(3),\n  empty: "".repeat(10)\n}\n', solution: 'const dash = "-"\nreturn {\n  dashes: dash.repeat(5),\n  pattern: "ha".repeat(3),\n  empty: "".repeat(10)\n}', tests: [{ input: [], expected: { dashes: "-----", pattern: "hahaha", empty: "" } }], hints: ["repeat(n) se string n baar repeat hoti hai", "0 ya negative number pe empty string return hoti hai"] },
  { id: "02-01-34", title: "Math object methods", starterCode: 'return {\n  pi: Math.PI,\n  sqrt16: Math.sqrt(16),\n  abs: Math.abs(-5),\n  ceil: Math.ceil(4.3),\n  floor: Math.floor(4.7),\n  round: Math.round(4.5),\n  random: typeof Math.random()\n}\n', solution: 'return {\n  pi: Math.PI,\n  sqrt16: Math.sqrt(16),\n  abs: Math.abs(-5),\n  ceil: Math.ceil(4.3),\n  floor: Math.floor(4.7),\n  round: Math.round(4.5),\n  random: typeof Math.random()\n}', tests: [{ input: [], expected: { pi: 3.141592653589793, sqrt16: 4, abs: 5, ceil: 5, floor: 4, round: 5, random: "number" } }], hints: ["Math.PI se pi milta hai", "ceil upar, floor neeche round karta hai"] },
  { id: "02-01-35", title: "Date object basics", starterCode: 'const now = new Date()\nreturn {\n  year: now.getFullYear(),\n  month: now.getMonth() + 1,\n  day: now.getDate(),\n  hours: now.getHours(),\n  isDate: now instanceof Date\n}\n', solution: 'const now = new Date()\nreturn {\n  year: now.getFullYear(),\n  month: now.getMonth() + 1,\n  day: now.getDate(),\n  hours: now.getHours(),\n  isDate: now instanceof Date\n}', tests: [{ input: [], expected: { year: 2026, month: 8, day: 6, hours: 12, isDate: true } }], hints: ["getFullYear() se year milta hai", "getMonth() 0-indexed hai (0 = January)"] },
  { id: "02-01-36", title: "JSON parse aur stringify", starterCode: 'const user = { name: "Hariom", age: 25, hobbies: ["coding", "reading"] }\nconst jsonString = JSON.stringify(user)\nconst parsed = JSON.parse(jsonString)\nreturn {\n  type: typeof jsonString,\n  parsed: parsed,\n  isDeepEqual: JSON.stringify(user) === JSON.stringify(parsed)\n}\n', solution: 'const user = { name: "Hariom", age: 25, hobbies: ["coding", "reading"] }\nconst jsonString = JSON.stringify(user)\nconst parsed = JSON.parse(jsonString)\nreturn {\n  type: typeof jsonString,\n  parsed: parsed,\n  isDeepEqual: JSON.stringify(user) === JSON.stringify(parsed)\n}', tests: [{ input: [], expected: { type: "string", parsed: { name: "Hariom", age: 25, hobbies: ["coding", "reading"] }, isDeepEqual: true } }], hints: ["JSON.stringify se object string banta hai", "JSON.parse se wapas object banta hai"] },
  { id: "02-01-37", title: "Spread operator practical", starterCode: 'const arr1 = [1, 2, 3]\nconst arr2 = [4, 5, 6]\nconst obj1 = { a: 1, b: 2 }\nconst obj2 = { b: 3, c: 4 }\nreturn {\n  mergedArr: [...arr1, ...arr2],\n  mergedObj: { ...obj1, ...obj2 }\n}\n', solution: 'const arr1 = [1, 2, 3]\nconst arr2 = [4, 5, 6]\nconst obj1 = { a: 1, b: 2 }\nconst obj2 = { b: 3, c: 4 }\nreturn {\n  mergedArr: [...arr1, ...arr2],\n  mergedObj: { ...obj1, ...obj2 }\n}', tests: [{ input: [], expected: { mergedArr: [1, 2, 3, 4, 5, 6], mergedObj: { a: 1, b: 3, c: 4 } } }], hints: ["...arr se elements expand hote hain", "Objects mein baaki ki value override hoti hai"] },
  { id: "02-01-38", title: "Rest parameters", starterCode: 'function sum(...numbers) {\n  // TODO\n}\n', solution: 'function sum(...numbers) {\n  return numbers.reduce((acc, n) => acc + n, 0)\n}', tests: [{ input: [1, 2, 3], expected: 6 }, { input: [10, 20, 30, 40], expected: 100 }], hints: ["...numbers se sab arguments array mein aate hain", "reduce se sum nikalo"] },
  { id: "02-01-39", title: "Default parameters", starterCode: 'function greet(name = "Guest", time = "Day") {\n  // TODO\n}\n', solution: 'function greet(name = "Guest", time = "Day") {\n  return `Good ${time}, ${name}!`\n}', tests: [{ input: ["Hariom", "Morning"], expected: "Good Morning, Hariom!" }, { input: [], expected: "Good Day, Guest!" }], hints: ["Parameter = defaultValue se default set hota hai", "Agar argument na mile to default use hota hai"] },
  { id: "02-01-40", title: "Primitive wrapper objects", starterCode: 'const str = "hello"\nreturn {\n  upper: str.toUpperCase(),\n  includes: str.includes("ell"),\n  slice: str.slice(1, 4),\n  startsWith: str.startsWith("he"),\n  endsWith: str.endsWith("lo")\n}\n', solution: 'const str = "hello"\nreturn {\n  upper: str.toUpperCase(),\n  includes: str.includes("ell"),\n  slice: str.slice(1, 4),\n  startsWith: str.startsWith("he"),\n  endsWith: str.endsWith("lo")\n}', tests: [{ input: [], expected: { upper: "HELLO", includes: true, slice: "ell", startsWith: true, endsWith: true } }], hints: ["Primitive strings temporary wrapper object create karte hain", "Methods call hote hain wrapper pe, phir wrapper discard hota hai"] },
  { id: "02-01-41", title: "Type conversion chart", starterCode: 'return {\n  numToString: String(123),\n  boolToString: String(true),\n  stringToNum: Number("456"),\n  boolToNum: Number(false),\n  numToBool: Boolean(0),\n  stringToBool: Boolean("hello"),\n  nullToNum: Number(null),\n  undefinedToNum: Number(undefined)\n}\n', solution: 'return {\n  numToString: String(123),\n  boolToString: String(true),\n  stringToNum: Number("456"),\n  boolToNum: Number(false),\n  numToBool: Boolean(0),\n  stringToBool: Boolean("hello"),\n  nullToNum: Number(null),\n  undefinedToNum: Number(undefined)\n}', tests: [{ input: [], expected: { numToString: "123", boolToString: "true", stringToNum: 456, boolToNum: 0, numToBool: false, stringToBool: true, nullToNum: 0, undefinedToNum: NaN } }], hints: ["String() se kuch bhi string ban sakta hai", "Number(null) = 0, Number(undefined) = NaN"] },
  { id: "02-01-42", title: "Tagged template literal", starterCode: 'function highlight(strings, ...values) {\n  return strings.reduce((result, str, i) => {\n    return result + str + (values[i] ? `[${values[i]}]` : "")\n  }, "")\n}\nconst name = "Hariom"\nconst age = 25\nreturn highlight`My name is ${name} and I am ${age} years old`\n', solution: 'function highlight(strings, ...values) {\n  return strings.reduce((result, str, i) => {\n    return result + str + (values[i] ? `[${values[i]}]` : "")\n  }, "")\n}\nconst name = "Hariom"\nconst age = 25\nreturn highlight`My name is ${name} and I am ${age} years old`', tests: [{ input: [], expected: "My name is [Hariom] and I am [25] years old" }], hints: ["Tagged template mein function pehle aata hai", "strings array aur values array alag milte hain"] },
  { id: "02-01-43", title: "String search methods", starterCode: 'const sentence = "JavaScript is awesome and JavaScript is fun"\nreturn {\n  indexOfFirst: sentence.indexOf("JavaScript"),\n  lastIndexOf: sentence.lastIndexOf("JavaScript"),\n  includes: sentence.includes("awesome"),\n  startsWith: sentence.startsWith("JavaScript"),\n  endsWith: sentence.endsWith("fun")\n}\n', solution: 'const sentence = "JavaScript is awesome and JavaScript is fun"\nreturn {\n  indexOfFirst: sentence.indexOf("JavaScript"),\n  lastIndexOf: sentence.lastIndexOf("JavaScript"),\n  includes: sentence.includes("awesome"),\n  startsWith: sentence.startsWith("JavaScript"),\n  endsWith: sentence.endsWith("fun")\n}', tests: [{ input: [], expected: { indexOfFirst: 0, lastIndexOf: 31, includes: true, startsWith: true, endsWith: true } }], hints: ["indexOf pehla occurrence index deta hai", "lastIndexOf last occurrence index deta hai"] },
  { id: "02-01-44", title: "String replace methods", starterCode: 'const text = "Hello World, Hello JavaScript"\nreturn {\n  firstReplace: text.replace("Hello", "Hi"),\n  allReplace: text.replaceAll("Hello", "Hi"),\n  regexReplace: text.replace(/Hello/g, "Hey")\n}\n', solution: 'const text = "Hello World, Hello JavaScript"\nreturn {\n  firstReplace: text.replace("Hello", "Hi"),\n  allReplace: text.replaceAll("Hello", "Hi"),\n  regexReplace: text.replace(/Hello/g, "Hey")\n}', tests: [{ input: [], expected: { firstReplace: "Hi World, Hello JavaScript", allReplace: "Hi World, Hi JavaScript", regexReplace: "Hey World, Hey JavaScript" } }], hints: ["replace() sirf pehla match replace karta hai", "replaceAll() ya regex with /g se sab replace hote hain"] },
  { id: "02-01-45", title: "Number parseInt aur parseFloat", starterCode: 'return {\n  parseInt: parseInt("42px"),\n  parseIntRadix: parseInt("1010", 2),\n  parseFloat: parseFloat("3.14em"),\n  parseIntNaN: parseInt("hello"),\n  unaryPlus: +"42",\n  doubleNot: !!1\n}\n', solution: 'return {\n  parseInt: parseInt("42px"),\n  parseIntRadix: parseInt("1010", 2),\n  parseFloat: parseFloat("3.14em"),\n  parseIntNaN: parseInt("hello"),\n  unaryPlus: +"42",\n  doubleNot: !!1\n}', tests: [{ input: [], expected: { parseInt: 42, parseIntRadix: 10, parseFloat: 3.14, parseIntNaN: NaN, unaryPlus: 42, doubleNot: true } }], hints: ["parseInt non-numeric characters ignore karta hai", "Radix parameter base specify karta hai"] },
  { id: "02-01-46", title: "String trim methods", starterCode: 'const messy = "  Hello World  "\nreturn {\n  trimmed: messy.trim(),\n  trimmedStart: messy.trimStart(),\n  trimmedEnd: messy.trimEnd(),\n  original: messy\n}\n', solution: 'const messy = "  Hello World  "\nreturn {\n  trimmed: messy.trim(),\n  trimmedStart: messy.trimStart(),\n  trimmedEnd: messy.trimEnd(),\n  original: messy\n}', tests: [{ input: [], expected: { trimmed: "Hello World", trimmedStart: "Hello World  ", trimmedEnd: "  Hello World", original: "  Hello World  " } }], hints: ["trim() dono taraf se spaces hatata hai", "trimStart() sirf shuru se, trimEnd() sirf end se"] },
  { id: "02-01-47", title: "WeakSet usage", starterCode: 'const visited = new WeakSet()\nconst obj1 = { page: "home" }\nconst obj2 = { page: "about" }\nvisited.add(obj1)\nvisited.add(obj2)\nreturn {\n  hasObj1: visited.has(obj1),\n  hasObj2: visited.has(obj2),\n  hasObj3: visited.has({ page: "home" })\n}\n', solution: 'const visited = new WeakSet()\nconst obj1 = { page: "home" }\nconst obj2 = { page: "about" }\nvisited.add(obj1)\nvisited.add(obj2)\nreturn {\n  hasObj1: visited.has(obj1),\n  hasObj2: visited.has(obj2),\n  hasObj3: visited.has({ page: "home" })\n}', tests: [{ input: [], expected: { hasObj1: true, hasObj2: true, hasObj3: false } }], hints: ["WeakSet mein sirf objects ho sakte hain", "Naya object alag reference hota hai"] },
  { id: "02-01-48", title: "Symbol.toPrimitive custom", starterCode: 'const money = {\n  amount: 100,\n  currency: "INR",\n  [Symbol.toPrimitive](hint) {\n    // TODO: hint ke according value return karo\n  }\n}\nreturn {\n  asNumber: +money,\n  asString: "" + money\n}\n', solution: 'const money = {\n  amount: 100,\n  currency: "INR",\n  [Symbol.toPrimitive](hint) {\n    if (hint === "number") return this.amount\n    return `${this.amount} ${this.currency}`\n  }\n}\nreturn {\n  asNumber: +money,\n  asString: "" + money\n}', tests: [{ input: [], expected: { asNumber: 100, asString: "100 INR" } }], hints: ["Symbol.toPrimitive se custom conversion hota hai", "hint 'number', 'string', ya 'default' ho sakta hai"] },
  { id: "02-01-49", title: "structuredClone deep copy", starterCode: 'const original = {\n  name: "Hariom",\n  address: { city: "Jaipur", pin: 302001 },\n  hobbies: ["coding", "reading"]\n}\nconst clone = structuredClone(original)\nclone.name = "Amit"\nclone.address.city = "Delhi"\nreturn {\n  original: original,\n  clone: clone\n}\n', solution: 'const original = {\n  name: "Hariom",\n  address: { city: "Jaipur", pin: 302001 },\n  hobbies: ["coding", "reading"]\n}\nconst clone = structuredClone(original)\nclone.name = "Amit"\nclone.address.city = "Delhi"\nreturn {\n  original: original,\n  clone: clone\n}', tests: [{ input: [], expected: { original: { name: "Hariom", address: { city: "Jaipur", pin: 302001 }, hobbies: ["coding", "reading"] }, clone: { name: "Amit", address: { city: "Delhi", pin: 302001 }, hobbies: ["coding", "reading"] } } }], hints: ["structuredClone deeply nested objects bhi clone karta hai", "Original object affect nahi hota"] },
  { id: "02-01-50", title: "Proxy basic usage", starterCode: 'const logs = []\nconst user = new Proxy({ name: "Hariom", age: 25 }, {\n  get(target, prop) {\n    // TODO: log karo aur value return karo\n  }\n})\nconst name = user.name\nconst age = user.age\nreturn { name, age, logs }\n', solution: 'const logs = []\nconst user = new Proxy({ name: "Hariom", age: 25 }, {\n  get(target, prop) {\n    logs.push("Accessed: " + prop)\n    return target[prop]\n  }\n})\nconst name = user.name\nconst age = user.age\nreturn { name, age, logs }', tests: [{ input: [], expected: { name: "Hariom", age: 25, logs: ["Accessed: name", "Accessed: age"] } }], hints: ["Proxy mein get trap property access intercept karta hai", "target original object hai"] },
])

// 02-02: reference-types-typeof (50 exercises)
writeLesson("02-data-types", 1, "reference-types-typeof", [
  { id: "02-02-01", title: "Array type check", starterCode: 'function isArray(val) {\n  // TODO\n}\n', solution: 'function isArray(val) {\n  return Array.isArray(val)\n}', tests: [{ input: [[1, 2, 3]], expected: true }, { input: ["hello"], expected: false }, { input: [{}], expected: false }], hints: ["Array.isArray() sabse reliable hai", "typeof [] 'object' return karta hai"] },
  { id: "02-02-02", title: "Object type identification", starterCode: 'function identifyType(val) {\n  // TODO: array, null, object, function, date return karo\n}\n', solution: 'function identifyType(val) {\n  if (val === null) return "null"\n  if (Array.isArray(val)) return "array"\n  if (val instanceof Date) return "date"\n  if (typeof val === "function") return "function"\n  return typeof val\n}', tests: [{ input: [42], expected: "number" }, { input: [null], expected: "null" }, { input: [[1, 2]], expected: "array" }, { input: [new Date()], expected: "date" }, { input: [function() {}], expected: "function" }], hints: ["typeof null 'object' return karta hai", "Array.isArray() aur instanceof use karo"] },
  { id: "02-02-03", title: "Shallow copy vs deep copy", starterCode: 'const original = { a: 1, b: { c: 2, d: 3 } }\nconst shallow = { ...original }\nshallow.a = 100\nshallow.b.c = 999\nreturn {\n  originalA: original.a,\n  originalBC: original.b.c,\n  shallowA: shallow.a,\n  shallowBC: shallow.b.c\n}\n', solution: 'const original = { a: 1, b: { c: 2, d: 3 } }\nconst shallow = { ...original }\nshallow.a = 100\nshallow.b.c = 999\nreturn {\n  originalA: original.a,\n  originalBC: original.b.c,\n  shallowA: shallow.a,\n  shallowBC: shallow.b.c\n}', tests: [{ input: [], expected: { originalA: 1, originalBC: 999, shallowA: 100, shallowBC: 999 } }], hints: ["Spread sirf shallow copy deta hai", "Nested objects reference share karte hain"] },
  { id: "02-02-04", title: "typeof for all types", starterCode: 'const values = [42, "hello", true, null, undefined, Symbol("x"), 42n, {}, [], function() {}, new Date()]\nreturn values.map(v => typeof v)\n', solution: 'const values = [42, "hello", true, null, undefined, Symbol("x"), 42n, {}, [], function() {}, new Date()]\nreturn values.map(v => typeof v)', tests: [{ input: [], expected: ["number", "string", "boolean", "object", "undefined", "symbol", "bigint", "object", "object", "function", "object"] }], hints: ["typeof null 'object' hai (JS ka bug)", "typeof [] bhi 'object' hai", "typeof function 'function' hai"] },
  { id: "02-02-05", title: "Reference equality vs value equality", starterCode: 'const a = { x: 1 }\nconst b = { x: 1 }\nconst c = a\nreturn {\n  aEqualsB: a === b,\n  aEqualsC: a === c,\n  deepEquals: JSON.stringify(a) === JSON.stringify(b)\n}\n', solution: 'const a = { x: 1 }\nconst b = { x: 1 }\nconst c = a\nreturn {\n  aEqualsB: a === b,\n  aEqualsC: a === c,\n  deepEquals: JSON.stringify(a) === JSON.stringify(b)\n}', tests: [{ input: [], expected: { aEqualsB: false, aEqualsC: true, deepEquals: true } }], hints: ["=== se reference compare hota hai objects ke liye", "JSON.stringify se shallow comparison ho sakti hai"] },
  { id: "02-02-06", title: "Array-like objects", starterCode: 'const arrayLike = { 0: "a", 1: "b", 2: "c", length: 3 }\nconst arr = Array.from(arrayLike)\nreturn {\n  type: typeof arrayLike,\n  converted: arr,\n  mapResult: arr.map(x => x.toUpperCase())\n}\n', solution: 'const arrayLike = { 0: "a", 1: "b", 2: "c", length: 3 }\nconst arr = Array.from(arrayLike)\nreturn {\n  type: typeof arrayLike,\n  converted: arr,\n  mapResult: arr.map(x => x.toUpperCase())\n}', tests: [{ input: [], expected: { type: "object", converted: ["a", "b", "c"], mapResult: ["A", "B", "C"] } }], hints: ["Array-like objects numeric indices aur length property rakhte hain", "Array.from() se real array banta hai"] },
  { id: "02-02-07", title: "Constructor identity check", starterCode: 'const arr = [1, 2, 3]\nconst obj = { a: 1 }\nconst date = new Date()\nconst regex = /hello/\nreturn {\n  arrConstructor: arr.constructor.name,\n  objConstructor: obj.constructor.name,\n  dateConstructor: date.constructor.name,\n  regexConstructor: regex.constructor.name\n}\n', solution: 'const arr = [1, 2, 3]\nconst obj = { a: 1 }\nconst date = new Date()\nconst regex = /hello/\nreturn {\n  arrConstructor: arr.constructor.name,\n  objConstructor: obj.constructor.name,\n  dateConstructor: date.constructor.name,\n  regexConstructor: regex.constructor.name\n}', tests: [{ input: [], expected: { arrConstructor: "Array", objConstructor: "Object", dateConstructor: "Date", regexConstructor: "RegExp" } }], hints: ["constructor.name se type milta hai", "Har object ka constructor hota hai"] },
  { id: "02-02-08", title: "instanceof check", starterCode: 'const arr = [1, 2, 3]\nconst date = new Date()\nconst regex = /test/\nconst promise = Promise.resolve(1)\nreturn {\n  arrIsArray: arr instanceof Array,\n  dateIsDate: date instanceof Date,\n  dateIsObject: date instanceof Object,\n  promiseIsPromise: promise instanceof Promise\n}\n', solution: 'const arr = [1, 2, 3]\nconst date = new Date()\nconst regex = /test/\nconst promise = Promise.resolve(1)\nreturn {\n  arrIsArray: arr instanceof Array,\n  dateIsDate: date instanceof Date,\n  dateIsObject: date instanceof Object,\n  promiseIsPromise: promise instanceof Promise\n}', tests: [{ input: [], expected: { arrIsArray: true, dateIsDate: true, dateIsObject: true, promiseIsPromise: true } }], hints: ["instanceof prototype chain check karta hai", "Date instanceof Object bhi true hota hai"] },
  { id: "02-02-09", title: "Pass by value vs reference", starterCode: 'let x = 5\nlet y = x\ny = 10\nconst obj1 = { val: 5 }\nconst obj2 = obj1\nobj2.val = 10\nreturn {\n  x: x,\n  y: y,\n  obj1Val: obj1.val,\n  obj2Val: obj2.val\n}\n', solution: 'let x = 5\nlet y = x\ny = 10\nconst obj1 = { val: 5 }\nconst obj2 = obj1\nobj2.val = 10\nreturn {\n  x: x,\n  y: y,\n  obj1Val: obj1.val,\n  obj2Val: obj2.val\n}', tests: [{ input: [], expected: { x: 5, y: 10, obj1Val: 10, obj2Val: 10 } }], hints: ["Primitives by value copy hote hain", "Objects by reference copy hote hain"] },
  { id: "02-02-10", title: "Mutable vs immutable data", starterCode: 'const str = "hello"\ntry { str[0] = "H" } catch(e) {}\nconst arr = [1, 2, 3]\narr[0] = 100\nreturn {\n  strUnchanged: str,\n  arrChanged: arr\n}\n', solution: 'const str = "hello"\ntry { str[0] = "H" } catch(e) {}\nconst arr = [1, 2, 3]\narr[0] = 100\nreturn {\n  strUnchanged: str,\n  arrChanged: arr\n}', tests: [{ input: [], expected: { strUnchanged: "hello", arrChanged: [100, 2, 3] } }], hints: ["Strings immutable hain — modify nahi ho sakti", "Arrays mutable hain — elements change ho sakte hain"] },
  { id: "02-02-11", title: "Object freeze vs seal", starterCode: 'const frozen = Object.freeze({ name: "Hariom", age: 25 })\ntry { frozen.age = 26 } catch(e) {}\ntry { frozen.name = "Amit" } catch(e) {}\nconst sealed = Object.seal({ name: "Rahul", age: 30 })\nsealed.age = 31\ntry { sealed.city = "Delhi" } catch(e) {}\nreturn {\n  frozen: frozen,\n  sealed: sealed\n}\n', solution: 'const frozen = Object.freeze({ name: "Hariom", age: 25 })\ntry { frozen.age = 26 } catch(e) {}\ntry { frozen.name = "Amit" } catch(e) {}\nconst sealed = Object.seal({ name: "Rahul", age: 30 })\nsealed.age = 31\ntry { sealed.city = "Delhi" } catch(e) {}\nreturn {\n  frozen: frozen,\n  sealed: sealed\n}', tests: [{ input: [], expected: { frozen: { name: "Hariom", age: 25 }, sealed: { name: "Rahul", age: 31 } } }], hints: ["freeze se kuch bhi modify nahi ho sakta", "seal se existing properties modify ho sakti hain, add/delete nahi"] },
  { id: "02-02-12", title: "Map vs Object for dynamic keys", starterCode: 'const map = new Map()\nconst objKey = { id: 1 }\nmap.set(objKey, "user1")\nmap.set(42, "answer")\nmap.set("name", "Hariom")\nreturn {\n  user: map.get(objKey),\n  answer: map.get(42),\n  name: map.get("name"),\n  size: map.size\n}\n', solution: 'const map = new Map()\nconst objKey = { id: 1 }\nmap.set(objKey, "user1")\nmap.set(42, "answer")\nmap.set("name", "Hariom")\nreturn {\n  user: map.get(objKey),\n  answer: map.get(42),\n  name: map.get("name"),\n  size: map.size\n}', tests: [{ input: [], expected: { user: "user1", answer: "answer", name: "Hariom", size: 3 } }], hints: ["Map mein koi bhi type key ho sakti hai", "Object mein sirf string/symbol keys hoti hain"] },
  { id: "02-02-13", title: "Prototype chain detection", starterCode: 'const obj = { x: 1, y: 2 }\nconst arr = [1, 2, 3]\nreturn {\n  objProto: Object.getPrototypeOf(obj).constructor.name,\n  arrProto: Object.getPrototypeOf(arr).constructor.name,\n  objHasOwnProperty: obj.hasOwnProperty("x"),\n  arrHasMap: typeof arr.map === "function"\n}\n', solution: 'const obj = { x: 1, y: 2 }\nconst arr = [1, 2, 3]\nreturn {\n  objProto: Object.getPrototypeOf(obj).constructor.name,\n  arrProto: Object.getPrototypeOf(arr).constructor.name,\n  objHasOwnProperty: obj.hasOwnProperty("x"),\n  arrHasMap: typeof arr.map === "function"\n}', tests: [{ input: [], expected: { objProto: "Object", arrProto: "Array", objHasOwnProperty: true, arrHasMap: true } }], hints: ["getPrototypeOf se prototype milta hai", "Prototype chain se methods inherit hote hain"] },
  { id: "02-02-14", title: "Deep comparison function", starterCode: 'function deepEqual(a, b) {\n  // TODO\n}\n', solution: 'function deepEqual(a, b) {\n  if (a === b) return true\n  if (a === null || b === null) return false\n  if (typeof a !== typeof b) return false\n  if (typeof a !== "object") return a === b\n  const keysA = Object.keys(a)\n  const keysB = Object.keys(b)\n  if (keysA.length !== keysB.length) return false\n  return keysA.every(key => deepEqual(a[key], b[key]))\n}', tests: [{ input: [{ x: 1, y: 2 }, { x: 1, y: 2 }], expected: true }, { input: [{ x: 1 }, { x: 2 }], expected: false }, { input: [{ a: { b: 1 } }, { a: { b: 1 } }], expected: true }], hints: ["Recursion se nested objects compare karo", "Pehle type aur length check karo"] },
  { id: "02-02-15", title: "WeakRef basics", starterCode: 'let obj = { data: "important" }\nconst ref = new WeakRef(obj)\nconst derefed = ref.deref()\nobj = null\nreturn {\n  derefedExists: derefed !== undefined,\n  derefedData: derefed?.data\n}\n', solution: 'let obj = { data: "important" }\nconst ref = new WeakRef(obj)\nconst derefed = ref.deref()\nobj = null\nreturn {\n  derefedExists: derefed !== undefined,\n  derefedData: derefed?.data\n}', tests: [{ input: [], expected: { derefedExists: true, derefedData: "important" } }], hints: ["WeakRef se garbage collection rokta nahi", "deref() se actual object milta hai"] },
  { id: "02-02-16", title: "TypedArray overview", starterCode: 'const int8 = new Int8Array([1, 2, 3])\nconst uint8 = new Uint8Array([255, 0, 128])\nconst float32 = new Float32Array([1.5, 2.5])\nreturn {\n  int8: Array.from(int8),\n  uint8: Array.from(uint8),\n  float32: Array.from(float32),\n  float32Bytes: float32.BYTES_PER_ELEMENT\n}\n', solution: 'const int8 = new Int8Array([1, 2, 3])\nconst uint8 = new Uint8Array([255, 0, 128])\nconst float32 = new Float32Array([1.5, 2.5])\nreturn {\n  int8: Array.from(int8),\n  uint8: Array.from(uint8),\n  float32: Array.from(float32),\n  float32Bytes: float32.BYTES_PER_ELEMENT\n}', tests: [{ input: [], expected: { int8: [1, 2, 3], uint8: [255, 0, 128], float32: [1.5, 2.5], float32Bytes: 4 } }], hints: ["TypedArrays fixed-size hain", "BYTES_PER_ELEMENT se size pata chalta hai"] },
  { id: "02-02-17", title: "Arguments object", starterCode: 'function sumAll() {\n  // TODO: arguments se sum nikalo\n}\nreturn sumAll(1, 2, 3, 4, 5)\n', solution: 'function sumAll() {\n  return Array.from(arguments).reduce((acc, n) => acc + n, 0)\n}\nreturn sumAll(1, 2, 3, 4, 5)', tests: [{ input: [], expected: 15 }], hints: ["arguments sirf regular functions mein hota hai", "Array.from() se array mein convert karo"] },
  { id: "02-02-18", title: "Symbol.iterator protocol", starterCode: 'const range = {\n  from: 1,\n  to: 5,\n  [Symbol.iterator]() {\n    // TODO\n  }\n}\nconst result = []\nfor (const num of range) {\n  result.push(num)\n}\nreturn result\n', solution: 'const range = {\n  from: 1,\n  to: 5,\n  [Symbol.iterator]() {\n    let current = this.from\n    const last = this.to\n    return {\n      next() {\n        if (current <= last) {\n          return { value: current++, done: false }\n        }\n        return { done: true }\n      }\n    }\n  }\n}\nconst result = []\nfor (const num of range) {\n  result.push(num)\n}\nreturn result', tests: [{ input: [], expected: [1, 2, 3, 4, 5] }], hints: ["Symbol.iterator method object ko iterable banata hai", "next() method { value, done } return karta hai"] },
  { id: "02-02-19", title: "Object.entries and fromEntries", starterCode: 'const original = { a: 1, b: 2, c: 3 }\nconst entries = Object.entries(original)\nconst doubled = entries.map(([k, v]) => [k, v * 2])\nconst rebuilt = Object.fromEntries(doubled)\nreturn {\n  entries: entries,\n  doubled: rebuilt\n}\n', solution: 'const original = { a: 1, b: 2, c: 3 }\nconst entries = Object.entries(original)\nconst doubled = entries.map(([k, v]) => [k, v * 2])\nconst rebuilt = Object.fromEntries(doubled)\nreturn {\n  entries: entries,\n  doubled: rebuilt\n}', tests: [{ input: [], expected: { entries: [["a", 1], ["b", 2], ["c", 3]], doubled: { a: 2, b: 4, c: 6 } } }], hints: ["Object.entries() se [key, value] pairs milte hain", "Object.fromEntries() se wapas object banta hai"] },
  { id: "02-02-20", title: "Object.keys values entries", starterCode: 'const user = { name: "Hariom", age: 25, city: "Jaipur" }\nreturn {\n  keys: Object.keys(user),\n  values: Object.values(user),\n  entries: Object.entries(user)\n}\n', solution: 'const user = { name: "Hariom", age: 25, city: "Jaipur" }\nreturn {\n  keys: Object.keys(user),\n  values: Object.values(user),\n  entries: Object.entries(user)\n}', tests: [{ input: [], expected: { keys: ["name", "age", "city"], values: ["Hariom", 25, "Jaipur"], entries: [["name", "Hariom"], ["age", 25], ["city", "Jaipur"]] } }], hints: ["Object.keys() sirf keys return karta hai", "Object.values() sirf values return karta hai"] },
  { id: "02-02-21", title: "Property descriptor", starterCode: 'const obj = { name: "Hariom" }\nObject.defineProperty(obj, "age", {\n  value: 25,\n  writable: false,\n  enumerable: true,\n  configurable: false\n})\ntry { obj.age = 26 } catch(e) {}\nreturn {\n  name: Object.getOwnPropertyDescriptor(obj, "name"),\n  age: obj.age,\n  enumerable: Object.getOwnPropertyDescriptor(obj, "age").enumerable\n}\n', solution: 'const obj = { name: "Hariom" }\nObject.defineProperty(obj, "age", {\n  value: 25,\n  writable: false,\n  enumerable: true,\n  configurable: false\n})\ntry { obj.age = 26 } catch(e) {}\nreturn {\n  name: Object.getOwnPropertyDescriptor(obj, "name"),\n  age: obj.age,\n  enumerable: Object.getOwnPropertyDescriptor(obj, "age").enumerable\n}', tests: [{ input: [], expected: { name: { value: "Hariom", writable: true, enumerable: true, configurable: true }, age: 25, enumerable: true } }], hints: ["defineProperty se property customize hoti hai", "writable: false se modify nahi ho sakta"] },
  { id: "02-02-22", title: "Proxy set trap", starterCode: 'const validator = {\n  set(target, prop, value) {\n    // TODO: age positive number hona chahiye\n  }\n}\nconst person = new Proxy({ name: "Hariom" }, validator)\nperson.age = 25\nperson.age = -5\nreturn { name: person.name, age: person.age }\n', solution: 'const validator = {\n  set(target, prop, value) {\n    if (prop === "age") {\n      if (typeof value !== "number" || value < 0) {\n        return false\n      }\n    }\n    target[prop] = value\n    return true\n  }\n}\nconst person = new Proxy({ name: "Hariom" }, validator)\nperson.age = 25\nperson.age = -5\nreturn { name: person.name, age: person.age }', tests: [{ input: [], expected: { name: "Hariom", age: 25 } }], hints: ["Proxy set trap property assignment intercept karta hai", "False return karne se assignment reject hota hai"] },
  { id: "02-02-23", title: "Map iteration methods", starterCode: 'const map = new Map()\nmap.set("a", 1)\nmap.set("b", 2)\nmap.set("c", 3)\nconst keys = [...map.keys()]\nconst values = [...map.values()]\nconst entries = [...map.entries()]\nreturn { keys, values, entries }\n', solution: 'const map = new Map()\nmap.set("a", 1)\nmap.set("b", 2)\nmap.set("c", 3)\nconst keys = [...map.keys()]\nconst values = [...map.values()]\nconst entries = [...map.entries()]\nreturn { keys, values, entries }', tests: [{ input: [], expected: { keys: ["a", "b", "c"], values: [1, 2, 3], entries: [["a", 1], ["b", 2], ["c", 3]] } }], hints: ["keys(), values(), entries() iterators return karte hain", "Spread se array mein convert karo"] },
  { id: "02-02-24", title: "Set operations", starterCode: 'const setA = new Set([1, 2, 3, 4])\nconst setB = new Set([3, 4, 5, 6])\nconst union = new Set([...setA, ...setB])\nconst intersection = new Set([...setA].filter(x => setB.has(x)))\nconst difference = new Set([...setA].filter(x => !setB.has(x)))\nreturn {\n  union: [...union],\n  intersection: [...intersection],\n  difference: [...difference]\n}\n', solution: 'const setA = new Set([1, 2, 3, 4])\nconst setB = new Set([3, 4, 5, 6])\nconst union = new Set([...setA, ...setB])\nconst intersection = new Set([...setA].filter(x => setB.has(x)))\nconst difference = new Set([...setA].filter(x => !setB.has(x)))\nreturn {\n  union: [...union],\n  intersection: [...intersection],\n  difference: [...difference]\n}', tests: [{ input: [], expected: { union: [1, 2, 3, 4, 5, 6], intersection: [3, 4], difference: [1, 2] } }], hints: ["Union: dono sets ke sab elements", "Intersection: sirf common elements", "Difference: pehle set mein jo doosre mein nahi"] },
  { id: "02-02-25", title: "Computed property names", starterCode: 'const prop = "age"\nconst method = "get" + "Name"\nconst obj = {\n  name: "Hariom",\n  [prop]: 25,\n  [method]() { return this.name }\n}\nreturn {\n  age: obj.age,\n  name: obj.getName()\n}\n', solution: 'const prop = "age"\nconst method = "get" + "Name"\nconst obj = {\n  name: "Hariom",\n  [prop]: 25,\n  [method]() { return this.name }\n}\nreturn {\n  age: obj.age,\n  name: obj.getName()\n}', tests: [{ input: [], expected: { age: 25, name: "Hariom" } }], hints: ["[] brackets mein expression daal sakte ho", "Computed names runtime pe evaluate hote hain"] },
  { id: "02-02-26", title: "Object.assign merge", starterCode: 'const target = { a: 1, b: 2 }\nconst source1 = { b: 3, c: 4 }\nconst source2 = { c: 5, d: 6 }\nconst merged = Object.assign(target, source1, source2)\nreturn merged\n', solution: 'const target = { a: 1, b: 2 }\nconst source1 = { b: 3, c: 4 }\nconst source2 = { c: 5, d: 6 }\nconst merged = Object.assign(target, source1, source2)\nreturn merged', tests: [{ input: [], expected: { a: 1, b: 3, c: 5, d: 6 } }], hints: ["Object.assign target modify karta hai", "Last value wins for duplicate keys"] },
  { id: "02-02-27", title: "for...in vs for...of", starterCode: 'const arr = ["a", "b", "c"]\nconst obj = { x: 1, y: 2, z: 3 }\nconst keys = []\nfor (const key in obj) keys.push(key)\nconst values = []\nfor (const val of arr) values.push(val)\nreturn { keys, values }\n', solution: 'const arr = ["a", "b", "c"]\nconst obj = { x: 1, y: 2, z: 3 }\nconst keys = []\nfor (const key in obj) keys.push(key)\nconst values = []\nfor (const val of arr) values.push(val)\nreturn { keys, values }', tests: [{ input: [], expected: { keys: ["x", "y", "z"], values: ["a", "b", "c"] } }], hints: ["for...in objects ke liye (keys iterate karta hai)", "for...of arrays ke liye (values iterate karta hai)"] },
  { id: "02-02-28", title: "Destructuring with rename", starterCode: 'const user = { name: "Hariom", age: 25, city: "Jaipur" }\nconst { name: userName, age: userAge, country = "India" } = user\nreturn { userName, userAge, country }\n', solution: 'const user = { name: "Hariom", age: 25, city: "Jaipur" }\nconst { name: userName, age: userAge, country = "India" } = user\nreturn { userName, userAge, country }', tests: [{ input: [], expected: { userName: "Hariom", userAge: 25, country: "India" } }], hints: ["oldName: newName se rename hota hai", "Default value = sign se set hoti hai"] },
  { id: "02-02-29", title: "Nested destructuring", starterCode: 'const data = {\n  user: { name: "Hariom", address: { city: "Jaipur", state: "Rajasthan" } },\n  score: 95\n}\nconst { user: { name, address: { city } }, score } = data\nreturn { name, city, score }\n', solution: 'const data = {\n  user: { name: "Hariom", address: { city: "Jaipur", state: "Rajasthan" } },\n  score: 95\n}\nconst { user: { name, address: { city } }, score } = data\nreturn { name, city, score }', tests: [{ input: [], expected: { name: "Hariom", city: "Jaipur", score: 95 } }], hints: ["Nested destructuring pattern match karta hai", "Depth tak jaake values extract hoti hain"] },
  { id: "02-02-30", title: "Array destructuring skip", starterCode: 'const [first, , third, ...rest] = [1, 2, 3, 4, 5, 6]\nreturn { first, third, rest }\n', solution: 'const [first, , third, ...rest] = [1, 2, 3, 4, 5, 6]\nreturn { first, third, rest }', tests: [{ input: [], expected: { first: 1, third: 3, rest: [4, 5, 6] } }], hints: [", se element skip hota hai", "...rest se baaki sab collect hota hai"] },
  { id: "02-02-31", title: "Function parameter destructuring", starterCode: 'function printUser({ name, age, city = "Unknown" }) {\n  return name + " (" + age + ") from " + city\n}\nreturn printUser({ name: "Hariom", age: 25, city: "Jaipur" })\n', solution: 'function printUser({ name, age, city = "Unknown" }) {\n  return name + " (" + age + ") from " + city\n}\nreturn printUser({ name: "Hariom", age: 25, city: "Jaipur" })', tests: [{ input: [], expected: "Hariom (25) from Jaipur" }], hints: ["Function parameters mein direct destructuring kar sakte ho", "Default values se missing properties handle hoti hain"] },
  { id: "02-02-32", title: "Spread in function call", starterCode: 'const numbers = [5, 3, 8, 1, 9, 2]\nconst min = Math.min(...numbers)\nconst max = Math.max(...numbers)\nreturn { min, max }\n', solution: 'const numbers = [5, 3, 8, 1, 9, 2]\nconst min = Math.min(...numbers)\nconst max = Math.max(...numbers)\nreturn { min, max }', tests: [{ input: [], expected: { min: 1, max: 9 } }], hints: ["...arr se array elements individual arguments ban jate hain", "Math.min/max spread se kaam karta hai"] },
  { id: "02-02-33", title: "Optional chaining with method call", starterCode: 'const user1 = { name: "Hariom", greet() { return "Hello!" } }\nconst user2 = { name: "Amit" }\nreturn {\n  greet1: user1.greet?.(),\n  greet2: user2.greet?.(),\n  upper1: user1.name?.toUpperCase?.(),\n  upper2: user2.name?.toUpperCase?.()\n}\n', solution: 'const user1 = { name: "Hariom", greet() { return "Hello!" } }\nconst user2 = { name: "Amit" }\nreturn {\n  greet1: user1.greet?.(),\n  greet2: user2.greet?.(),\n  upper1: user1.name?.toUpperCase?.(),\n  upper2: user2.name?.toUpperCase?.()\n}', tests: [{ input: [], expected: { greet1: "Hello!", greet2: undefined, upper1: "HARIOM", upper2: "AMIT" } }], hints: ["?.() se safe method call hota hai", "Agar method exist nahi karta to undefined return hota hai"] },
  { id: "02-02-34", title: "JSON replacer function", starterCode: 'const data = { name: "Hariom", age: 25, password: "secret123", city: "Jaipur" }\nconst safe = JSON.stringify(data, (key, value) => {\n  if (key === "password") return "[HIDDEN]"\n  return value\n}, 2)\nreturn JSON.parse(safe)\n', solution: 'const data = { name: "Hariom", age: 25, password: "secret123", city: "Jaipur" }\nconst safe = JSON.stringify(data, (key, value) => {\n  if (key === "password") return "[HIDDEN]"\n  return value\n}, 2)\nreturn JSON.parse(safe)', tests: [{ input: [], expected: { name: "Hariom", age: 25, password: "[HIDDEN]", city: "Jaipur" } }], hints: ["Replacer function har key-value pair pe call hota hai", "Modify value ya undefined return kar sakte ho"] },
  { id: "02-02-35", title: "Object groupBy", starterCode: 'const people = [\n  { name: "Hariom", dept: "IT" },\n  { name: "Rahul", dept: "HR" },\n  { name: "Amit", dept: "IT" },\n  { name: "Priya", dept: "HR" }\n]\nconst grouped = people.reduce((acc, p) => {\n  acc[p.dept] = acc[p.dept] || []\n  acc[p.dept].push(p.name)\n  return acc\n}, {})\nreturn grouped\n', solution: 'const people = [\n  { name: "Hariom", dept: "IT" },\n  { name: "Rahul", dept: "HR" },\n  { name: "Amit", dept: "IT" },\n  { name: "Priya", dept: "HR" }\n]\nconst grouped = people.reduce((acc, p) => {\n  acc[p.dept] = acc[p.dept] || []\n  acc[p.dept].push(p.name)\n  return acc\n}, {})\nreturn grouped', tests: [{ input: [], expected: { IT: ["Hariom", "Amit"], HR: ["Rahul", "Priya"] } }], hints: ["Reduce se object build karo", "Har group ko initialize karo array se"] },
  { id: "02-02-36", title: "MapToObject conversion", starterCode: 'const map = new Map([["name", "Hariom"], ["age", 25], ["city", "Jaipur"]])\nconst obj = Object.fromEntries(map)\nconst backToMap = new Map(Object.entries(obj))\nreturn {\n  obj: obj,\n  mapSize: backToMap.size\n}\n', solution: 'const map = new Map([["name", "Hariom"], ["age", 25], ["city", "Jaipur"]])\nconst obj = Object.fromEntries(map)\nconst backToMap = new Map(Object.entries(obj))\nreturn {\n  obj: obj,\n  mapSize: backToMap.size\n}', tests: [{ input: [], expected: { obj: { name: "Hariom", age: 25, city: "Jaipur" }, mapSize: 3 } }], hints: ["Object.fromEntries() se Map->Object hota hai", "new Map(Object.entries()) se Object->Map hota hai"] },
  { id: "02-02-37", title: "Property existence check", starterCode: 'const obj = { name: "Hariom", age: 25 }\nreturn {\n  dotAccess: obj.name !== undefined,\n  inOperator: "age" in obj,\n  hasOwn: Object.hasOwn(obj, "name"),\n  hasOwnProperty: obj.hasOwnProperty("city"),\n  optionalChaining: obj?.city\n}\n', solution: 'const obj = { name: "Hariom", age: 25 }\nreturn {\n  dotAccess: obj.name !== undefined,\n  inOperator: "age" in obj,\n  hasOwn: Object.hasOwn(obj, "name"),\n  hasOwnProperty: obj.hasOwnProperty("city"),\n  optionalChaining: obj?.city\n}', tests: [{ input: [], expected: { dotAccess: true, inOperator: true, hasOwn: true, hasOwnProperty: false, optionalChaining: undefined } }], hints: ["in operator prototype chain bhi check karta hai", "Object.hasOwn() sirf own property check karta hai"] },
  { id: "02-02-38", title: "Symbol species pattern", starterCode: 'class MyArray extends Array {\n  static get [Symbol.species]() {\n    return Array\n  }\n}\nconst myArr = new MyArray(1, 2, 3)\nconst mapped = myArr.map(x => x * 2)\nreturn {\n  isMyArray: myArr instanceof MyArray,\n  isArray: mapped instanceof Array,\n  isMyArrayType: mapped instanceof MyArray\n}\n', solution: 'class MyArray extends Array {\n  static get [Symbol.species]() {\n    return Array\n  }\n}\nconst myArr = new MyArray(1, 2, 3)\nconst mapped = myArr.map(x => x * 2)\nreturn {\n  isMyArray: myArr instanceof MyArray,\n  isArray: mapped instanceof Array,\n  isMyArrayType: mapped instanceof MyArray\n}', tests: [{ input: [], expected: { isMyArray: true, isArray: true, isMyArrayType: false } }], hints: ["Symbol.species se derived methods ka return type control hota hai", "map(), filter() jaise methods species use karte hain"] },
  { id: "02-02-39", title: "Immutability patterns", starterCode: 'const state = { user: { name: "Hariom", scores: [10, 20, 30] } }\nconst newState = {\n  ...state,\n  user: {\n    ...state.user,\n    name: "Amit",\n    scores: [...state.user.scores, 40]\n  }\n}\nreturn {\n  original: state,\n  updated: newState\n}\n', solution: 'const state = { user: { name: "Hariom", scores: [10, 20, 30] } }\nconst newState = {\n  ...state,\n  user: {\n    ...state.user,\n    name: "Amit",\n    scores: [...state.user.scores, 40]\n  }\n}\nreturn {\n  original: state,\n  updated: newState\n}', tests: [{ input: [], expected: { original: { user: { name: "Hariom", scores: [10, 20, 30] } }, updated: { user: { name: "Amit", scores: [10, 20, 30, 40] } } } }], hints: ["Spread operator se shallow copy banao", "Nested update ke liye nested spread use karo"] },
  { id: "02-02-40", title: "Object pattern matching", starterCode: 'const response = { status: 200, data: { users: [{ name: "Hariom" }] } }\nconst { status, data: { users: [firstUser] } } = response\nreturn { status, userName: firstUser.name }\n', solution: 'const response = { status: 200, data: { users: [{ name: "Hariom" }] } }\nconst { status, data: { users: [firstUser] } } = response\nreturn { status, userName: firstUser.name }', tests: [{ input: [], expected: { status: 200, userName: "Hariom" } }], hints: ["Nested destructuring se deep values extract hoti hain", "Array destructuring bhi nested ho sakti hai"] },
  { id: "02-02-41", title: "Proxy has trap", starterCode: 'const range = new Proxy({ min: 1, max: 100 }, {\n  has(target, prop) {\n    const num = Number(prop)\n    return !isNaN(num) && num >= target.min && num <= target.max\n  }\n})\nreturn {\n  has50: 50 in range,\n  has150: 150 in range,\n  hasName: "name" in range\n}\n', solution: 'const range = new Proxy({ min: 1, max: 100 }, {\n  has(target, prop) {\n    const num = Number(prop)\n    return !isNaN(num) && num >= target.min && num <= target.max\n  }\n})\nreturn {\n  has50: 50 in range,\n  has150: 150 in range,\n  hasName: "name" in range\n}', tests: [{ input: [], expected: { has50: true, has150: false, hasName: false } }], hints: ["Proxy has trap 'in' operator intercept karta hai", "Custom logic se range check kar sakte ho"] },
  { id: "02-02-42", title: "Proxy deleteProperty trap", starterCode: 'const protected = new Proxy({ name: "Hariom", secret: "xyz" }, {\n  deleteProperty(target, prop) {\n    if (prop === "secret") return false\n    delete target[prop]\n    return true\n  }\n})\ndelete protected.name\ntry { delete protected.secret } catch(e) {}\nreturn { hasName: "name" in protected, hasSecret: "secret" in protected }\n', solution: 'const protected = new Proxy({ name: "Hariom", secret: "xyz" }, {\n  deleteProperty(target, prop) {\n    if (prop === "secret") return false\n    delete target[prop]\n    return true\n  }\n})\ndelete protected.name\ntry { delete protected.secret } catch(e) {}\nreturn { hasName: "name" in protected, hasSecret: "secret" in protected }', tests: [{ input: [], expected: { hasName: false, hasSecret: true } }], hints: ["deleteProperty trap deletion intercept karta hai", "False return karne se deletion prevent hota hai"] },
  { id: "02-02-43", title: "TypedArray buffer view", starterCode: 'const buffer = new ArrayBuffer(16)\nconst int32 = new Int32Array(buffer)\nconst uint8 = new Uint8Array(buffer)\nint32[0] = 42\nreturn {\n  int32First: int32[0],\n  uint8First: uint8[0],\n  uint8Second: uint8[1],\n  bufferSize: buffer.byteLength\n}\n', solution: 'const buffer = new ArrayBuffer(16)\nconst int32 = new Int32Array(buffer)\nconst uint8 = new Uint8Array(buffer)\nint32[0] = 42\nreturn {\n  int32First: int32[0],\n  uint8First: uint8[0],\n  uint8Second: uint8[1],\n  bufferSize: buffer.byteLength\n}', tests: [{ input: [], expected: { int32First: 42, uint8First: 42, uint8Second: 0, bufferSize: 16 } }], hints: ["ArrayBuffer raw memory hai", "Different TypedArrays same buffer ko alag view se access kar sakte hain"] },
  { id: "02-02-44", title: "Promise.allSettled", starterCode: 'const promises = [\n  Promise.resolve(1),\n  Promise.reject("error"),\n  Promise.resolve(3)\n]\nconst results = await Promise.allSettled(promises)\nreturn results.map(r => ({ status: r.status, value: r.value || r.reason }))\n', solution: 'const promises = [\n  Promise.resolve(1),\n  Promise.reject("error"),\n  Promise.resolve(3)\n]\nconst results = await Promise.allSettled(promises)\nreturn results.map(r => ({ status: r.status, value: r.value || r.reason }))', tests: [{ input: [], expected: [{ status: "fulfilled", value: 1 }, { status: "rejected", value: "error" }, { status: "fulfilled", value: 3 }] }], hints: ["Promise.allSettled kabhi reject nahi hota", "Har promise ka status aur value/reason milta hai"] },
  { id: "02-02-45", title: "Promise.any basic", starterCode: 'const promises = [\n  new Promise((_, reject) => setTimeout(() => reject("slow"), 100)),\n  new Promise(resolve => setTimeout(() => resolve("fast"), 50)),\n  new Promise(resolve => setTimeout(() => resolve("faster"), 30))\n]\nconst result = await Promise.any(promises)\nreturn result\n', solution: 'const promises = [\n  new Promise((_, reject) => setTimeout(() => reject("slow"), 100)),\n  new Promise(resolve => setTimeout(() => resolve("fast"), 50)),\n  new Promise(resolve => setTimeout(() => resolve("faster"), 30))\n]\nconst result = await Promise.any(promises)\nreturn result', tests: [{ input: [], expected: "faster" }], hints: ["Promise.any pehla resolved promise return karta hai", "Agar sab reject ho jayein to AggregateError throw hota hai"] },
  { id: "02-02-46", title: "Proxy apply trap", starterCode: 'function sum(a, b) { return a + b }\nconst proxiedSum = new Proxy(sum, {\n  apply(target, thisArg, args) {\n    return target(...args) + " (proxied)"\n  }\n})\nreturn {\n  normal: sum(2, 3),\n  proxied: proxiedSum(2, 3)\n}\n', solution: 'function sum(a, b) { return a + b }\nconst proxiedSum = new Proxy(sum, {\n  apply(target, thisArg, args) {\n    return target(...args) + " (proxied)"\n  }\n})\nreturn {\n  normal: sum(2, 3),\n  proxied: proxiedSum(2, 3)\n}', tests: [{ input: [], expected: { normal: 5, proxied: "5 (proxied)" } }], hints: ["Proxy apply trap function calls intercept karta hai", "thisArg wo context hai jispe call hota hai"] },
  { id: "02-02-47", title: "Proxy getPrototypeOf trap", starterCode: 'const proto = { greet() { return "Hello!" } }\nconst obj = new Proxy({}, {\n  getPrototypeOf() {\n    return proto\n  }\n})\nreturn {\n  hasGreet: typeof obj.greet === "function",\n  greeting: obj.greet()\n}\n', solution: 'const proto = { greet() { return "Hello!" } }\nconst obj = new Proxy({}, {\n  getPrototypeOf() {\n    return proto\n  }\n})\nreturn {\n  hasGreet: typeof obj.greet === "function",\n  greeting: obj.greet()\n}', tests: [{ input: [], expected: { hasGreet: true, greeting: "Hello!" } }], hints: ["getPrototypeOf trap prototype control karta hai", "Custom prototype se methods inherit hote hain"] },
  { id: "02-02-48", title: "Object literal enhancement", starterCode: 'const name = "Hariom"\nconst age = 25\nconst greet = function() { return "Hello!" }\nconst user = { name, age, greet, toString() { return this.name } }\nreturn {\n  str: user.toString(),\n  hello: user.greet()\n}\n', solution: 'const name = "Hariom"\nconst age = 25\nconst greet = function() { return "Hello!" }\nconst user = { name, age, greet, toString() { return this.name } }\nreturn {\n  str: user.toString(),\n  hello: user.greet()\n}', tests: [{ input: [], expected: { str: "Hariom", hello: "Hello!" } }], hints: ["Shorthand properties: { name } instead of { name: name }", "Method shorthand: greet() {} instead of greet: function() {}"] },
  { id: "02-02-49", title: "WeakMap for private data", starterCode: 'const privateData = new WeakMap()\nclass User {\n  constructor(name, password) {\n    this.name = name\n    privateData.set(this, { password })\n  }\n  checkPassword(pwd) {\n    return privateData.get(this).password === pwd\n  }\n}\nconst user = new User("Hariom", "secret123")\nreturn {\n  name: user.name,\n  correct: user.checkPassword("secret123"),\n  wrong: user.checkPassword("wrong")\n}\n', solution: 'const privateData = new WeakMap()\nclass User {\n  constructor(name, password) {\n    this.name = name\n    privateData.set(this, { password })\n  }\n  checkPassword(pwd) {\n    return privateData.get(this).password === pwd\n  }\n}\nconst user = new User("Hariom", "secret123")\nreturn {\n  name: user.name,\n  correct: user.checkPassword("secret123"),\n  wrong: user.checkPassword("wrong")\n}', tests: [{ input: [], expected: { name: "Hariom", correct: true, wrong: false } }], hints: ["WeakMap mein objects keys hoti hain — private data ke liye perfect", "Instance delete ho jaye to data bhi garbage collect hota hai"] },
  { id: "02-02-50", title: "Proxy construct trap", starterCode: 'function Person(name) { this.name = name }\nconst ProxiedPerson = new Proxy(Person, {\n  construct(target, args) {\n    const instance = new target(...args)\n    instance.createdAt = new Date().toISOString()\n    return instance\n  }\n})\nconst p = new ProxiedPerson("Hariom")\nreturn {\n  name: p.name,\n  hasCreatedAt: typeof p.createdAt === "string"\n}\n', solution: 'function Person(name) { this.name = name }\nconst ProxiedPerson = new Proxy(Person, {\n  construct(target, args) {\n    const instance = new target(...args)\n    instance.createdAt = new Date().toISOString()\n    return instance\n  }\n})\nconst p = new ProxiedPerson("Hariom")\nreturn {\n  name: p.name,\n  hasCreatedAt: typeof p.createdAt === "string"\n}', tests: [{ input: [], expected: { name: "Hariom", hasCreatedAt: true } }], hints: ["Proxy construct trap new operator intercept karta hai", "Instance modify karke return kar sakte ho"] },
])

// 02-03: coercion-truthy-falsy (50 exercises)
writeLesson("02-data-types", 2, "coercion-truthy-falsy", [
  { id: "02-03-01", title: "Implicit string coercion", starterCode: 'return {\n  numPlusStr: 5 + "3",\n  strPlusNum: "5" + 3,\n  numPlusBool: 5 + true,\n  numPlusNull: 5 + null,\n  numPlusUndef: 5 + undefined\n}\n', solution: 'return {\n  numPlusStr: 5 + "3",\n  strPlusNum: "5" + 3,\n  numPlusBool: 5 + true,\n  numPlusNull: 5 + null,\n  numPlusUndef: 5 + undefined\n}', tests: [{ input: [], expected: { numPlusStr: "53", strPlusNum: "53", numPlusBool: 6, numPlusNull: 5, numPlusUndef: NaN } }], hints: ["'+' operator jab string involve ho to concat karta hai", "true = 1, null = 0, undefined = NaN"] },
  { id: "02-03-02", title: "Implicit number coercion", starterCode: 'return {\n  strMinus: "10" - 3,\n  strMul: "5" * 2,\n  strDiv: "20" / 4,\n  strMod: "10" % 3,\n  boolMinus: true - 1,\n  nullMul: null * 5\n}\n', solution: 'return {\n  strMinus: "10" - 3,\n  strMul: "5" * 2,\n  strDiv: "20" / 4,\n  strMod: "10" % 3,\n  boolMinus: true - 1,\n  nullMul: null * 5\n}', tests: [{ input: [], expected: { strMinus: 7, strMul: 10, strDiv: 5, strMod: 1, boolMinus: 0, nullMul: 0 } }], hints: ["Arithmetic operators hamesha number coercion karte hain", "-, *, /, % sab number mein convert karte hain"] },
  { id: "02-03-03", title: "Comparison operator coercion", starterCode: 'return {\n  numStr: 5 == "5",\n  numStrStrict: 5 === "5",\n  boolNum: 1 == true,\n  boolNumStrict: 1 === true,\n  nullUndef: null == undefined,\n  nullUndefStrict: null === undefined,\n  emptyStrZero: "" == 0,\n  spaceStrZero: " " == 0\n}\n', solution: 'return {\n  numStr: 5 == "5",\n  numStrStrict: 5 === "5",\n  boolNum: 1 == true,\n  boolNumStrict: 1 === true,\n  nullUndef: null == undefined,\n  nullUndefStrict: null === undefined,\n  emptyStrZero: "" == 0,\n  spaceStrZero: " " == 0\n}', tests: [{ input: [], expected: { numStr: true, numStrStrict: false, boolNum: true, boolNumStrict: false, nullUndef: true, nullUndefStrict: false, emptyStrZero: true, spaceStrZero: true } }], hints: ["== type coercion karta hai, === nahi", "null == undefined true hai, null === undefined false"] },
  { id: "02-03-04", title: "Truthy values identify karo", starterCode: 'const testValues = [1, -1, "0", "false", [], {}, function() {}, Infinity, -Infinity, Symbol("x"), 42n]\nreturn testValues.map(v => ({\n  value: String(v),\n  isTruthy: Boolean(v)\n}))\n', solution: 'const testValues = [1, -1, "0", "false", [], {}, function() {}, Infinity, -Infinity, Symbol("x"), 42n]\nreturn testValues.map(v => ({\n  value: String(v),\n  isTruthy: Boolean(v)\n}))', tests: [{ input: [], expected: [{ value: "1", isTruthy: true }, { value: "-1", isTruthy: true }, { value: "0", isTruthy: true }, { value: "false", isTruthy: true }, { value: "[object Object]", isTruthy: true }, { value: "function() {}", isTruthy: true }, { value: "Infinity", isTruthy: true }, { value: "-Infinity", isTruthy: true }, { value: "Symbol(x)", isTruthy: true }, { value: "42", isTruthy: true }] }], hints: ["Non-empty strings, non-zero numbers, objects, arrays — sab truthy hain", "0, '', null, undefined, NaN, false — sab falsy hain"] },
  { id: "02-03-05", title: "Falsy values identify karo", starterCode: 'const testValues = [false, 0, -0, 0n, "", null, undefined, NaN]\nreturn testValues.map(v => ({\n  value: String(v),\n  type: typeof v,\n  isFalsy: !v\n}))\n', solution: 'const testValues = [false, 0, -0, 0n, "", null, undefined, NaN]\nreturn testValues.map(v => ({\n  value: String(v),\n  type: typeof v,\n  isFalsy: !v\n}))', tests: [{ input: [], expected: [{ value: "false", type: "boolean", isFalsy: true }, { value: "0", type: "number", isFalsy: true }, { value: "0", type: "number", isFalsy: true }, { value: "0", type: "bigint", isFalsy: true }, { value: "", type: "string", isFalsy: true }, { value: "null", type: "object", isFalsy: true }, { value: "undefined", type: "undefined", isFalsy: true }, { value: "NaN", type: "number", isFalsy: true }] }], hints: ["Sirf 6 falsy values hain: false, 0, '', null, undefined, NaN", "0n (BigInt zero) bhi falsy hai"] },
  { id: "02-03-06", title: "Double NOT for boolean", starterCode: 'return {\n  emptyStr: !!"",\n  nonEmptyStr: !!"hello",\n  zero: !!0,\n  nonZero: !!42,\n  null: !!null,\n  obj: !!{},\n  arr: !![],\n  nan: !!NaN\n}\n', solution: 'return {\n  emptyStr: !!"",\n  nonEmptyStr: !!"hello",\n  zero: !!0,\n  nonZero: !!42,\n  null: !!null,\n  obj: !!{},\n  arr: !![],\n  nan: !!NaN\n}', tests: [{ input: [], expected: { emptyStr: false, nonEmptyStr: true, zero: false, nonZero: true, null: false, obj: true, arr: true, nan: false } }], hints: ["! pehle boolean mein convert karta hai, phir negate karta hai", "!! value ka boolean equivalent deta hai"] },
  { id: "02-03-07", title: "Logical operators return values", starterCode: 'return {\n  or1: "hello" || "world",\n  or2: "" || "default",\n  or3: null || "fallback",\n  and1: "hello" && "world",\n  and2: "" && "world",\n  and3: null && "value"\n}\n', solution: 'return {\n  or1: "hello" || "world",\n  or2: "" || "default",\n  or3: null || "fallback",\n  and1: "hello" && "world",\n  and2: "" && "world",\n  and3: null && "value"\n}', tests: [{ input: [], expected: { or1: "hello", or2: "default", or3: "fallback", and1: "world", and2: "", and3: null } }], hints: ["|| pehla truthy value return karta hai", "&& last value return karta hai agar sab truthy ho"] },
  { id: "02-03-08", title: "Nullish coalescing vs OR", starterCode: 'const zero = 0\nconst emptyStr = ""\nconst falseVal = false\nreturn {\n  orZero: zero || "default",\n  nullishZero: zero ?? "default",\n  orEmpty: emptyStr || "default",\n  nullishEmpty: emptyStr ?? "default",\n  orFalse: falseVal || "default",\n  nullishFalse: falseVal ?? "default"\n}\n', solution: 'const zero = 0\nconst emptyStr = ""\nconst falseVal = false\nreturn {\n  orZero: zero || "default",\n  nullishZero: zero ?? "default",\n  orEmpty: emptyStr || "default",\n  nullishEmpty: emptyStr ?? "default",\n  orFalse: falseVal || "default",\n  nullishFalse: falseVal ?? "default"\n}', tests: [{ input: [], expected: { orZero: "default", nullishZero: 0, orEmpty: "default", nullishEmpty: "", orFalse: "default", nullishFalse: false } }], hints: ["|| falsy values ke liye bhi default deta hai", "?? sirf null/undefined ke liye default deta hai"] },
  { id: "02-03-09", title: "String to number coercion edge cases", starterCode: 'return {\n  emptyString: Number(""),\n  spaceString: Number(" "),\n  trueString: Number("true"),\n  hexString: Number("0xFF"),\n  infinityString: Number("Infinity"),\n  nullString: Number(null),\n  undefinedString: Number(undefined),\n  nanString: Number("hello")\n}\n', solution: 'return {\n  emptyString: Number(""),\n  spaceString: Number(" "),\n  trueString: Number("true"),\n  hexString: Number("0xFF"),\n  infinityString: Number("Infinity"),\n  nullString: Number(null),\n  undefinedString: Number(undefined),\n  nanString: Number("hello")\n}', tests: [{ input: [], expected: { emptyString: 0, spaceString: 0, trueString: NaN, hexString: 255, infinityString: Infinity, nullString: 0, undefinedString: NaN, nanString: NaN } }], hints: ["Number('') = 0 hota hai", "Number(null) = 0, Number(undefined) = NaN"] },
  { id: "02-03-10", title: "Boolean coercion rules", starterCode: 'return {\n  numberToBool: Boolean(1),\n  zeroToBool: Boolean(0),\n  emptyArrToBool: Boolean([]),\n  emptyObjToBool: Boolean({}),\n  stringToBool: Boolean("0"),\n  zeroStringToBool: Boolean("false")\n}\n', solution: 'return {\n  numberToBool: Boolean(1),\n  zeroToBool: Boolean(0),\n  emptyArrToBool: Boolean([]),\n  emptyObjToBool: Boolean({}),\n  stringToBool: Boolean("0"),\n  zeroStringToBool: Boolean("false")\n}', tests: [{ input: [], expected: { numberToBool: true, zeroToBool: false, emptyArrToBool: true, emptyObjToBool: true, stringToBool: true, zeroStringToBool: true } }], hints: ["Empty arrays aur objects truthy hain", "Non-empty strings truthy hain — '0' aur 'false' bhi"] },
  { id: "02-03-11", title: "== type coercion deep dive", starterCode: 'return {\n  emptyArrNull: [] == null,\n  emptyArrFalse: [] == false,\n  emptyArrZero: [] == 0,\n  emptyStrNull: "" == null,\n  falseNull: false == null,\n  trueOne: true == 1,\n  trueTwo: true == 2\n}\n', solution: 'return {\n  emptyArrNull: [] == null,\n  emptyArrFalse: [] == false,\n  emptyArrZero: [] == 0,\n  emptyStrNull: "" == null,\n  falseNull: false == null,\n  trueOne: true == 1,\n  trueTwo: true == 2\n}', tests: [{ input: [], expected: { emptyArrNull: false, emptyArrFalse: true, emptyArrZero: true, emptyStrNull: false, falseNull: false, trueOne: true, trueTwo: false } }], hints: ["[] == false hota hai kyunki [] -> '' -> 0, false -> 0", "null sirf undefined ke barabar hota hai =="] },
  { id: "02-03-12", title: "Unary plus conversion", starterCode: 'return {\n  string: +"42",\n  boolean: +true,\n  null: +null,\n  undefined: +undefined,\n  emptyStr: +"",\n  nan: +"hello",\n  float: +"3.14"\n}\n', solution: 'return {\n  string: +"42",\n  boolean: +true,\n  null: +null,\n  undefined: +undefined,\n  emptyStr: +"",\n  nan: +"hello",\n  float: +"3.14"\n}', tests: [{ input: [], expected: { string: 42, boolean: 1, null: 0, undefined: NaN, emptyStr: 0, nan: NaN, float: 3.14 } }], hints: ["+ operator sabse fast type coercion karta hai", "+'' = 0, +null = 0, +undefined = NaN"] },
  { id: "02-03-13", title: "Ternary operator practical", starterCode: 'function getAgeCategory(age) {\n  // TODO: use nested ternary\n  // < 13: "Child", 13-17: "Teen", 18-64: "Adult", 65+: "Senior"\n}\n', solution: 'function getAgeCategory(age) {\n  return age < 13 ? "Child" : age < 18 ? "Teen" : age < 65 ? "Adult" : "Senior"\n}', tests: [{ input: [10], expected: "Child" }, { input: [15], expected: "Teen" }, { input: [30], expected: "Adult" }, { input: [70], expected: "Senior" }], hints: ["condition ? trueValue : falseValue", "Nested ternary mein readability ka khayal rakho"] },
  { id: "02-03-14", title: "Short circuit evaluation", starterCode: 'const user = { name: "Hariom" }\nconst name = user && user.name\nconst city = user && user.address && user.address.city\nconst defaultVal = null || undefined || "fallback"\nreturn { name, city, defaultVal }\n', solution: 'const user = { name: "Hariom" }\nconst name = user && user.name\nconst city = user && user.address && user.address.city\nconst defaultVal = null || undefined || "fallback"\nreturn { name, city, defaultVal }', tests: [{ input: [], expected: { name: "Hariom", city: undefined, defaultVal: "fallback" } }], hints: ["&& pehla falsy value ya last value return karta hai", "|| pehla truthy value return karta hai"] },
  { id: "02-03-15", title: "== vs === behavior", starterCode: 'const a = "42"\nconst b = 42\nreturn {\n  looseEqual: a == b,\n  strictEqual: a === b,\n  looseNullUndef: null == undefined,\n  strictNullUndef: null === undefined\n}\n', solution: 'const a = "42"\nconst b = 42\nreturn {\n  looseEqual: a == b,\n  strictEqual: a === b,\n  looseNullUndef: null == undefined,\n  strictNullUndef: null === undefined\n}', tests: [{ input: [], expected: { looseEqual: true, strictEqual: false, looseNullUndef: true, strictNullUndef: false } }], hints: ["== type coercion karta hai", "=== strictly compare karta hai"] },
  { id: "02-03-16", title: "Bitwise NOT operator", starterCode: 'const num = 42\nreturn {\n  bitwiseNot: ~num,\n  doubleNot: ~~num,\n  floorExample: ~~3.9,\n  indexOf: ~"hello".indexOf("x"),\n  indexOfFound: ~"hello".indexOf("e")\n}\n', solution: 'const num = 42\nreturn {\n  bitwiseNot: ~num,\n  doubleNot: ~~num,\n  floorExample: ~~3.9,\n  indexOf: ~"hello".indexOf("x"),\n  indexOfFound: ~"hello".indexOf("e")\n}', tests: [{ input: [], expected: { bitwiseNot: -43, doubleNot: 42, floorExample: 3, indexOf: 0, indexOfFound: -2 } }], hints: ["~num = -(num+1)", "~~num se floor hota hai (double bitwise NOT)", "~(-1) = 0 — truthy/falsy check ke liye use hota hai"] },
  { id: "02-03-17", title: "Implicit toString coercion", starterCode: 'return {\n  arrayStr: [1, 2, 3].toString(),\n  objStr: ({ a: 1 }).toString(),\n  numArr: [10] + [20],\n  arrConcat: [1, 2] + [3, 4]\n}\n', solution: 'return {\n  arrayStr: [1, 2, 3].toString(),\n  objStr: ({ a: 1 }).toString(),\n  numArr: [10] + [20],\n  arrConcat: [1, 2] + [3, 4]\n}', tests: [{ input: [], expected: { arrayStr: "1,2,3", objStr: "[object Object]", numArr: "1020", arrConcat: "1,23,4" } }], hints: ["Array toString comma-separated string deta hai", "+ operator dono taraf ke values toString karta hai"] },
  { id: "02-03-18", title: "Relational operator coercion", starterCode: 'return {\n  numStr: 5 > "3",\n  strStr: "10" > "9",\n  boolNum: true < 2,\n  nullNum: null >= 0,\n  nanCompare: NaN > NaN,\n  nanEqual: NaN === NaN\n}\n', solution: 'return {\n  numStr: 5 > "3",\n  strStr: "10" > "9",\n  boolNum: true < 2,\n  nullNum: null >= 0,\n  nanCompare: NaN > NaN,\n  nanEqual: NaN === NaN\n}', tests: [{ input: [], expected: { numStr: true, strStr: false, boolNum: true, nullNum: true, nanCompare: false, nanEqual: false } }], hints: ["String comparison alphabetical hota hai", "NaN kisi se bhi compare nahi hota"] },
  { id: "02-03-19", title: "Switch statement coercion", starterCode: 'function test(x) {\n  switch(x) {\n    case 0: return "zero"\n    case "": return "empty"\n    case false: return "false"\n    case null: return "null"\n    default: return "other"\n  }\n}\nreturn {\n  test0: test(0),\n  testEmpty: test(""),\n  testFalse: test(false),\n  testNull: test(null)\n}\n', solution: 'function test(x) {\n  switch(x) {\n    case 0: return "zero"\n    case "": return "empty"\n    case false: return "false"\n    case null: return "null"\n    default: return "other"\n  }\n}\nreturn {\n  test0: test(0),\n  testEmpty: test(""),\n  testFalse: test(false),\n  testNull: test(null)\n}', tests: [{ input: [], expected: { test0: "zero", testEmpty: "empty", testFalse: "false", testNull: "null" } }], hints: ["Switch === comparison use karta hai", "Pehla match milte hi break ki zaroorat nahi return se"] },
  { id: "02-03-20", title: "Arithmetic edge cases", starterCode: 'return {\n  stringMul: "4" * "3",\n  boolMul: true * "10",\n  nullMul: null * 5,\n  undefMul: undefined * 5,\n  infAdd: Infinity + Infinity,\n  infSub: Infinity - Infinity,\n  nanAdd: NaN + 1\n}\n', solution: 'return {\n  stringMul: "4" * "3",\n  boolMul: true * "10",\n  nullMul: null * 5,\n  undefMul: undefined * 5,\n  infAdd: Infinity + Infinity,\n  infSub: Infinity - Infinity,\n  nanAdd: NaN + 1\n}', tests: [{ input: [], expected: { stringMul: 12, boolMul: 10, nullMul: 0, undefMul: NaN, infAdd: Infinity, infSub: NaN, nanAdd: NaN } }], hints: ["Strings number mein convert hoti hain arithmetic pe", "NaN kisi bhi operation mein NaN return karta hai"] },
  { id: "02-03-21", title: "Coercion in if conditions", starterCode: 'const values = [0, 1, "", "0", "1", null, undefined, NaN, [], {}, [0]]\nreturn values.map(v => ({\n  value: String(v),\n  entersIf: !!v\n}))\n', solution: 'const values = [0, 1, "", "0", "1", null, undefined, NaN, [], {}, [0]]\nreturn values.map(v => ({\n  value: String(v),\n  entersIf: !!v\n}))', tests: [{ input: [], expected: [{ value: "0", entersIf: false }, { value: "1", entersIf: true }, { value: "", entersIf: false }, { value: "0", entersIf: true }, { value: "1", entersIf: true }, { value: "null", entersIf: false }, { value: "undefined", entersIf: false }, { value: "NaN", entersIf: false }, { value: "", entersIf: true }, { value: "[object Object]", entersIf: true }, { value: "0", entersIf: true }] }], hints: ["if condition mein value coerced hoti hai boolean mein", "[0] truthy hai, [] bhi truthy hai"] },
  { id: "02-03-22", title: "JSON.stringify edge cases", starterCode: 'const data = {\n  undef: undefined,\n  func: function() {},\n  nan: NaN,\n  inf: Infinity,\n  sym: Symbol("x"),\n  date: new Date(),\n  regex: /test/\n}\nreturn JSON.parse(JSON.stringify(data))\n', solution: 'const data = {\n  undef: undefined,\n  func: function() {},\n  nan: NaN,\n  inf: Infinity,\n  sym: Symbol("x"),\n  date: new Date(),\n  regex: /test/\n}\nreturn JSON.parse(JSON.stringify(data))', tests: [{ input: [], expected: { nan: null, inf: null, date: "2026-08-06T00:00:00.000Z", regex: {} } }], hints: ["undefined, function, symbol keys dropped ho jate hain", "NaN, Infinity null ban jate hain", "Date string ban jati hai"] },
  { id: "02-03-23", title: "Array.includes with coercion", starterCode: 'const arr = [0, 1, 2, 3, "0", "1"]\nreturn {\n  hasZero: arr.includes(0),\n  hasStringZero: arr.includes("0"),\n  indexOfZero: arr.indexOf(0),\n  indexOfStringZero: arr.indexOf("0")\n}\n', solution: 'const arr = [0, 1, 2, 3, "0", "1"]\nreturn {\n  hasZero: arr.includes(0),\n  hasStringZero: arr.includes("0"),\n  indexOfZero: arr.indexOf(0),\n  indexOfStringZero: arr.indexOf("0")\n}', tests: [{ input: [], expected: { hasZero: true, hasStringZero: true, indexOfZero: 0, indexOfStringZero: 4 } }], hints: ["includes() === comparison use karta hai", "0 aur '0' alag hain === se"] },
  { id: "02-03-24", title: "Map key coercion", starterCode: 'const map = new Map()\nmap.set(1, "one")\nmap.set("1", "string one")\nmap.set(true, "boolean")\nreturn {\n  numKey: map.get(1),\n  strKey: map.get("1"),\n  boolKey: map.get(true),\n  size: map.size\n}\n', solution: 'const map = new Map()\nmap.set(1, "one")\nmap.set("1", "string one")\nmap.set(true, "boolean")\nreturn {\n  numKey: map.get(1),\n  strKey: map.get("1"),\n  boolKey: map.get(true),\n  size: map.size\n}', tests: [{ input: [], expected: { numKey: "one", strKey: "string one", boolKey: "boolean", size: 3 } }], hints: ["Map === comparison use karta hai keys ke liye", "1 aur '1' alag keys hain Map mein"] },
  { id: "02-03-25", title: "Set value coercion", starterCode: 'const set = new Set()\nset.add(1)\nset.add("1")\nset.add(true)\nset.add(1)\nreturn {\n  hasNum: set.has(1),\n  hasStr: set.has("1"),\n  hasBool: set.has(true),\n  size: set.size\n}\n', solution: 'const set = new Set()\nset.add(1)\nset.add("1")\nset.add(true)\nset.add(1)\nreturn {\n  hasNum: set.has(1),\n  hasStr: set.has("1"),\n  hasBool: set.has(true),\n  size: set.size\n}', tests: [{ input: [], expected: { hasNum: true, hasStr: true, hasBool: true, size: 3 } }], hints: ["Set bhi === comparison use karta hai", "Duplicate add nahi hota — same value wala"] },
  { id: "02-03-26", title: "Proxy set with coercion", starterCode: 'const numObj = new Proxy({ val: 0 }, {\n  set(target, prop, value) {\n    if (typeof value !== "number") {\n      throw new TypeError("Only numbers allowed")\n    }\n    target[prop] = value\n    return true\n  }\n})\nnumObj.val = 42\ntry { numObj.val = "42" } catch(e) { return { val: numObj.val, error: e.message } }\nreturn { val: numObj.val }\n', solution: 'const numObj = new Proxy({ val: 0 }, {\n  set(target, prop, value) {\n    if (typeof value !== "number") {\n      throw new TypeError("Only numbers allowed")\n    }\n    target[prop] = value\n    return true\n  }\n})\nnumObj.val = 42\ntry { numObj.val = "42" } catch(e) { return { val: numObj.val, error: e.message } }\nreturn { val: numObj.val }', tests: [{ input: [], expected: { val: 42, error: "Only numbers allowed" } }], hints: ["Proxy set trap type validation ke liye useful hai", "Throw se assignment prevent hoti hai"] },
  { id: "02-03-27", title: "Implicit object coercion", starterCode: 'const obj = {\n  valueOf() { return 42 },\n  toString() { return "custom" }\n}\nreturn {\n  withPlus: +obj,\n  withString: "" + obj,\n  withNumber: Number(obj)\n}\n', solution: 'const obj = {\n  valueOf() { return 42 },\n  toString() { return "custom" }\n}\nreturn {\n  withPlus: +obj,\n  withString: "" + obj,\n  withNumber: Number(obj)\n}', tests: [{ input: [], expected: { withPlus: 42, withString: "custom", withNumber: 42 } }], hints: ["Number context mein valueOf call hota hai", "String context mein toString call hota hai"] },
  { id: "02-03-28", title: "JSON.parse coercion", starterCode: 'const json = \'{"num": 42, "str": "hello", "bool": true, "nullVal": null, "arr": [1,2,3]}\'\nconst parsed = JSON.parse(json)\nreturn {\n  numType: typeof parsed.num,\n  strType: typeof parsed.str,\n  boolType: typeof parsed.bool,\n  nullType: typeof parsed.nullVal,\n  arrType: Array.isArray(parsed.arr)\n}\n', solution: 'const json = \'{"num": 42, "str": "hello", "bool": true, "nullVal": null, "arr": [1,2,3]}\'\nconst parsed = JSON.parse(json)\nreturn {\n  numType: typeof parsed.num,\n  strType: typeof parsed.str,\n  boolType: typeof parsed.bool,\n  nullType: typeof parsed.nullVal,\n  arrType: Array.isArray(parsed.arr)\n}', tests: [{ input: [], expected: { numType: "number", strType: "string", boolType: "boolean", nullType: "object", arrType: true } }], hints: ["JSON.parse correct types preserve karta hai", "null typeof 'object' return karta hai"] },
  { id: "02-03-29", title: "toJSON method", starterCode: 'const obj = {\n  x: 1,\n  y: 2,\n  toJSON() {\n    return { sum: this.x + this.y }\n  }\n}\nconst result = JSON.stringify(obj)\nreturn JSON.parse(result)\n', solution: 'const obj = {\n  x: 1,\n  y: 2,\n  toJSON() {\n    return { sum: this.x + this.y }\n  }\n}\nconst result = JSON.stringify(obj)\nreturn JSON.parse(result)', tests: [{ input: [], expected: { sum: 3 } }], hints: ["toJSON() method JSON.stringify ko control karta hai", "Custom serialization possible hai"] },
  { id: "02-03-30", title: "Number.isFinite vs isFinite", starterCode: 'return {\n  isFiniteInf: isFinite(Infinity),\n  numberIsFiniteInf: Number.isFinite(Infinity),\n  isFiniteNum: isFinite(42),\n  numberIsFiniteNum: Number.isFinite(42),\n  isFiniteStr: isFinite("42"),\n  numberIsFiniteStr: Number.isFinite("42")\n}\n', solution: 'return {\n  isFiniteInf: isFinite(Infinity),\n  numberIsFiniteInf: Number.isFinite(Infinity),\n  isFiniteNum: isFinite(42),\n  numberIsFiniteNum: Number.isFinite(42),\n  isFiniteStr: isFinite("42"),\n  numberIsFiniteStr: Number.isFinite("42")\n}', tests: [{ input: [], expected: { isFiniteInf: false, numberIsFiniteInf: false, isFiniteNum: true, numberIsFiniteNum: true, isFiniteStr: true, numberIsFiniteStr: false } }], hints: ["isFinite pehle number mein convert karta hai", "Number.isFinite sirf numbers ke liye check karta hai"] },
  { id: "02-03-31", title: "Proxy in trap", starterCode: 'const data = new Proxy({ name: "Hariom", age: 25 }, {\n  has(target, prop) {\n    return prop in target && target[prop] !== undefined\n  }\n})\nreturn {\n  hasName: "name" in data,\n  hasCity: "city" in data\n}\n', solution: 'const data = new Proxy({ name: "Hariom", age: 25 }, {\n  has(target, prop) {\n    return prop in target && target[prop] !== undefined\n  }\n})\nreturn {\n  hasName: "name" in data,\n  hasCity: "city" in data\n}', tests: [{ input: [], expected: { hasName: true, hasCity: false } }], hints: ["Proxy has trap 'in' operator intercept karta hai", "Custom logic se property existence check kar sakte ho"] },
  { id: "02-03-32", title: "String to array coercion", starterCode: 'const str = "hello"\nconst arr = Array.from(str)\nconst spread = [...str]\nconst split = str.split("")\nreturn {\n  from: arr,\n  spread: spread,\n  split: split\n}\n', solution: 'const str = "hello"\nconst arr = Array.from(str)\nconst spread = [...str]\nconst split = str.split("")\nreturn {\n  from: arr,\n  spread: spread,\n  split: split\n}', tests: [{ input: [], expected: { from: ["h", "e", "l", "l", "o"], spread: ["h", "e", "l", "l", "o"], split: ["h", "e", "l", "l", "o"] } }], hints: ["Array.from() se string array ban jati hai", "Spread operator bhi same kaam karta hai"] },
  { id: "02-03-33", title: "Number.isInteger check", starterCode: 'return {\n  isInt42: Number.isInteger(42),\n  isInt42_5: Number.isInteger(42.5),\n  isIntStr: Number.isInteger("42"),\n  isIntNaN: Number.isInteger(NaN),\n  isIntInf: Number.isInteger(Infinity)\n}\n', solution: 'return {\n  isInt42: Number.isInteger(42),\n  isInt42_5: Number.isInteger(42.5),\n  isIntStr: Number.isInteger("42"),\n  isIntNaN: Number.isInteger(NaN),\n  isIntInf: Number.isInteger(Infinity)\n}', tests: [{ input: [], expected: { isInt42: true, isInt42_5: false, isIntStr: false, isIntNaN: false, isIntInf: false } }], hints: ["Number.isInteger() sirf integers ke liye true deta hai", "Strings aur NaN ke liye false"] },
  { id: "02-03-34", title: "Proxy ownKeys trap", starterCode: 'const obj = new Proxy({ _secret: "hidden", name: "Hariom", age: 25 }, {\n  ownKeys(target) {\n    return Object.keys(target).filter(k => !k.startsWith("_"))\n  }\n})\nreturn {\n  keys: Object.keys(obj),\n  hasSecret: "_secret" in Object.getOwnPropertyNames(obj)\n}\n', solution: 'const obj = new Proxy({ _secret: "hidden", name: "Hariom", age: 25 }, {\n  ownKeys(target) {\n    return Object.keys(target).filter(k => !k.startsWith("_"))\n  }\n})\nreturn {\n  keys: Object.keys(obj),\n  hasSecret: "_secret" in Object.getOwnPropertyNames(obj)\n}', tests: [{ input: [], expected: { keys: ["name", "age"], hasSecret: false } }], hints: ["Proxy ownKeys trap Object.keys() intercept karta hai", "Private properties hide kar sakte ho"] },
  { id: "02-03-35", title: "Logical assignment operators", starterCode: 'let a = 0\nlet b = ""\nlet c = "hello"\na ||= "default"\nb ||= "default"\nc ||= "default"\nreturn { a, b, c }\n', solution: 'let a = 0\nlet b = ""\nlet c = "hello"\na ||= "default"\nb ||= "default"\nc ||= "default"\nreturn { a, b, c }', tests: [{ input: [], expected: { a: "default", b: "default", c: "hello" } }], hints: ["||= sirf falsy value pe assign karta hai", "Truthy value pe kuch nahi hota"] },
  { id: "02-03-36", title: "Nullish assignment", starterCode: 'let a = 0\nlet b = ""\nlet c = null\nlet d = undefined\na ??= 10\nb ??= "default"\nc ??= "assigned"\nd ??= "assigned"\nreturn { a, b, c, d }\n', solution: 'let a = 0\nlet b = ""\nlet c = null\nlet d = undefined\na ??= 10\nb ??= "default"\nc ??= "assigned"\nd ??= "assigned"\nreturn { a, b, c, d }', tests: [{ input: [], expected: { a: 0, b: "", c: "assigned", d: "assigned" } }], hints: ["??= sirf null/undefined pe assign karta hai", "0 aur '' ko valid value maanta hai"] },
  { id: "02-03-37", title: "Proxy getPrototypeOf with toString", starterCode: 'const obj = new Proxy({ x: 1 }, {\n  get(target, prop) {\n    if (prop === "toString") return () => "Proxy object"\n    return target[prop]\n  }\n})\nreturn {\n  x: obj.x,\n  str: "" + obj\n}\n', solution: 'const obj = new Proxy({ x: 1 }, {\n  get(target, prop) {\n    if (prop === "toString") return () => "Proxy object"\n    return target[prop]\n  }\n})\nreturn {\n  x: obj.x,\n  str: "" + obj\n}', tests: [{ input: [], expected: { x: 1, str: "Proxy object" } }], hints: ["Proxy get trap mein toString override kar sakte ho", "String context mein custom toString call hota hai"] },
  { id: "02-03-38", title: "Number parseFloat vs parseInt", starterCode: 'return {\n  parseFloat: [parseFloat("3.14"), parseFloat("3.14abc"), parseFloat("abc")],\n  parseInt: [parseInt("3.14"), parseInt("3.14abc"), parseInt("abc")],\n  parseIntRadix: [parseInt("10", 2), parseInt("ff", 16), parseInt("77", 8)]\n}\n', solution: 'return {\n  parseFloat: [parseFloat("3.14"), parseFloat("3.14abc"), parseFloat("abc")],\n  parseInt: [parseInt("3.14"), parseInt("3.14abc"), parseInt("abc")],\n  parseIntRadix: [parseInt("10", 2), parseInt("ff", 16), parseInt("77", 8)]\n}', tests: [{ input: [], expected: { parseFloat: [3.14, 3.14, NaN], parseInt: [3, 3, NaN], parseIntRadix: [2, 255, 63] } }], hints: ["parseFloat decimal point tak parse karta hai", "parseInt radix parameter se base set karta hai"] },
  { id: "02-03-39", title: "Proxy construct with validation", starterCode: 'function User(name, age) {\n  this.name = name\n  this.age = age\n}\nconst ValidatedUser = new Proxy(User, {\n  construct(target, args) {\n    if (args[1] < 0) throw new Error("Age cannot be negative")\n    return new target(...args)\n  }\n})\nconst user1 = new ValidatedUser("Hariom", 25)\ntry {\n  const user2 = new ValidatedUser("Amit", -5)\n} catch(e) {\n  return { user1: user1.name, error: e.message }\n}\n', solution: 'function User(name, age) {\n  this.name = name\n  this.age = age\n}\nconst ValidatedUser = new Proxy(User, {\n  construct(target, args) {\n    if (args[1] < 0) throw new Error("Age cannot be negative")\n    return new target(...args)\n  }\n})\nconst user1 = new ValidatedUser("Hariom", 25)\ntry {\n  const user2 = new ValidatedUser("Amit", -5)\n} catch(e) {\n  return { user1: user1.name, error: e.message }\n}', tests: [{ input: [], expected: { user1: "Hariom", error: "Age cannot be negative" } }], hints: ["Proxy construct trap constructor validation ke liye hai", "Throw se invalid instances ban kar sakte ho"] },
  { id: "02-03-40", title: "Template literal expression coercion", starterCode: 'const num = 42\nconst bool = true\nconst arr = [1, 2, 3]\nconst obj = { x: 1 }\nreturn {\n  numStr: `Number: ${num}`,\n  boolStr: `Bool: ${bool}`,\n  arrStr: `Array: ${arr}`,\n  objStr: `Obj: ${obj}`\n}\n', solution: 'const num = 42\nconst bool = true\nconst arr = [1, 2, 3]\nconst obj = { x: 1 }\nreturn {\n  numStr: `Number: ${num}`,\n  boolStr: `Bool: ${bool}`,\n  arrStr: `Array: ${arr}`,\n  objStr: `Obj: ${obj}`\n}', tests: [{ input: [], expected: { numStr: "Number: 42", boolStr: "Bool: true", arrStr: "Array: 1,2,3", objStr: "Obj: [object Object]" } }], hints: ["Template literals automatically toString call karte hain", "Objects ke liye [object Object] aata hai"] },
  { id: "02-03-41", title: "Proxy defineProperty trap", starterCode: 'const data = new Proxy({}, {\n  defineProperty(target, prop, descriptor) {\n    if (prop === "age" && descriptor.value < 0) {\n      return false\n    }\n    return Reflect.defineProperty(target, prop, descriptor)\n  }\n})\ndata.age = 25\ntry {\n  Object.defineProperty(data, "age", { value: -5 })\n} catch(e) {}\nreturn { age: data.age }\n', solution: 'const data = new Proxy({}, {\n  defineProperty(target, prop, descriptor) {\n    if (prop === "age" && descriptor.value < 0) {\n      return false\n    }\n    return Reflect.defineProperty(target, prop, descriptor)\n  }\n})\ndata.age = 25\ntry {\n  Object.defineProperty(data, "age", { value: -5 })\n} catch(e) {}\nreturn { age: data.age }', tests: [{ input: [], expected: { age: 25 } }], hints: ["Proxy defineProperty trap defineProperty intercept karta hai", "Reflect.defineProperty se default behavior follow hota hai"] },
  { id: "02-03-42", title: "Array.from with mapFn", starterCode: 'const result1 = Array.from({ length: 5 }, (_, i) => i + 1)\nconst result2 = Array.from("hello", c => c.toUpperCase())\nreturn {\n  range: result1,\n  upper: result2\n}\n', solution: 'const result1 = Array.from({ length: 5 }, (_, i) => i + 1)\nconst result2 = Array.from("hello", c => c.toUpperCase())\nreturn {\n  range: result1,\n  upper: result2\n}', tests: [{ input: [], expected: { range: [1, 2, 3, 4, 5], upper: ["H", "E", "L", "L", "O"] } }], hints: ["Array.from第二个参数 se mapping hota hai", "Array-like objects se array bana sakte ho"] },
  { id: "02-03-43", title: "Symbol.toPrimitive with hint", starterCode: 'const temp = {\n  celsius: 100,\n  [Symbol.toPrimitive](hint) {\n    if (hint === "number") return this.celsius\n    if (hint === "string") return this.celsius + "°C"\n    return this.celsius + 273.15\n  }\n}\nreturn {\n  asNum: +temp,\n  asStr: "" + temp,\n  asDefault: temp + 0\n}\n', solution: 'const temp = {\n  celsius: 100,\n  [Symbol.toPrimitive](hint) {\n    if (hint === "number") return this.celsius\n    if (hint === "string") return this.celsius + "°C"\n    return this.celsius + 273.15\n  }\n}\nreturn {\n  asNum: +temp,\n  asStr: "" + temp,\n  asDefault: temp + 0\n}', tests: [{ input: [], expected: { asNum: 100, asStr: "100°C", asDefault: 373.15 } }], hints: ["hint 'default' tab aata hai jab + use hota hai", "Har hint ke liye alag behavior de sakte ho"] },
  { id: "02-03-44", title: "Proxy get with receiver", starterCode: 'const handler = {\n  get(target, prop, receiver) {\n    if (prop === "fullName") {\n      return target.firstName + " " + target.lastName\n    }\n    return Reflect.get(target, prop, receiver)\n  }\n}\nconst person = new Proxy({ firstName: "Hariom", lastName: "Kumar" }, handler)\nreturn {\n  fullName: person.fullName,\n  firstName: person.firstName\n}\n', solution: 'const handler = {\n  get(target, prop, receiver) {\n    if (prop === "fullName") {\n      return target.firstName + " " + target.lastName\n    }\n    return Reflect.get(target, prop, receiver)\n  }\n}\nconst person = new Proxy({ firstName: "Hariom", lastName: "Kumar" }, handler)\nreturn {\n  fullName: person.fullName,\n  firstName: person.firstName\n}', tests: [{ input: [], expected: { fullName: "Hariom Kumar", firstName: "Hariom" } }], hints: ["Receiver wo object hai jispe property access ho rahi hai", "Reflect.get se default behavior follow hota hai"] },
  { id: "02-03-45", title: "Structured clone with transferables", starterCode: 'const buffer = new ArrayBuffer(8)\nconst view = new Uint8Array(buffer)\nview[0] = 42\nconst clone = structuredClone(buffer)\nconst cloneView = new Uint8Array(clone)\nreturn {\n  original: view[0],\n  cloned: cloneView[0],\n  sameBuffer: buffer === clone\n}\n', solution: 'const buffer = new ArrayBuffer(8)\nconst view = new Uint8Array(buffer)\nview[0] = 42\nconst clone = structuredClone(buffer)\nconst cloneView = new Uint8Array(clone)\nreturn {\n  original: view[0],\n  cloned: cloneView[0],\n  sameBuffer: buffer === clone\n}', tests: [{ input: [], expected: { original: 42, cloned: 42, sameBuffer: false } }], hints: ["structuredClone ArrayBuffers bhi clone karta hai", "Cloned buffer alag hota hai original se"] },
  { id: "02-03-46", title: "Number.EPSILON comparison", starterCode: 'const a = 0.1 + 0.2\nconst b = 0.3\nreturn {\n  directEqual: a === b,\n  epsilonEqual: Math.abs(a - b) < Number.EPSILON,\n  epsilon: Number.EPSILON\n}\n', solution: 'const a = 0.1 + 0.2\nconst b = 0.3\nreturn {\n  directEqual: a === b,\n  epsilonEqual: Math.abs(a - b) < Number.EPSILON,\n  epsilon: Number.EPSILON\n}', tests: [{ input: [], expected: { directEqual: false, epsilonEqual: true, epsilon: 2.220446049250313e-16 } }], hints: ["Number.EPSILON se floating point comparison hota hai", "Math.abs(a - b) < Number.EPSILON se safe comparison hota hai"] },
  { id: "02-03-47", title: "Proxy apply with new", starterCode: 'function Factory(type) {\n  this.type = type\n}\nconst ProxiedFactory = new Proxy(Factory, {\n  apply(target, thisArg, args) {\n    return new target(...args)\n  }\n})\nconst obj = ProxiedFactory("user")\nreturn {\n  type: obj.type,\n  instanceof: obj instanceof Factory\n}\n', solution: 'function Factory(type) {\n  this.type = type\n}\nconst ProxiedFactory = new Proxy(Factory, {\n  apply(target, thisArg, args) {\n    return new target(...args)\n  }\n})\nconst obj = ProxiedFactory("user")\nreturn {\n  type: obj.type,\n  instanceof: obj instanceof Factory\n}', tests: [{ input: [], expected: { type: "user", "instanceof": true } }], hints: ["Proxy apply trap mein new target() se instance bana sakte ho", "Function call ko constructor call mein convert kar sakte ho"] },
  { id: "02-03-48", title: "Proxy preventExtensions trap", starterCode: 'const data = new Proxy({ name: "Hariom" }, {\n  preventExtensions(target) {\n    return Object.preventExtensions(target)\n  }\n})\nObject.preventExtensions(data)\ntry {\n  data.age = 25\n} catch(e) {}\nreturn {\n  hasName: "name" in data,\n  hasAge: "age" in data\n}\n', solution: 'const data = new Proxy({ name: "Hariom" }, {\n  preventExtensions(target) {\n    return Object.preventExtensions(target)\n  }\n})\nObject.preventExtensions(data)\ntry {\n  data.age = 25\n} catch(e) {}\nreturn {\n  hasName: "name" in data,\n  hasAge: "age" in data\n}', tests: [{ input: [], expected: { hasName: true, hasAge: false } }], hints: ["Proxy preventExtensions trap extensions prevent karta hai", "Naye properties add nahi ho sakte"] },
  { id: "02-03-49", title: "Object.is vs ===", starterCode: 'return {\n  isMinusZero: Object.is(-0, 0),\n  strictMinusZero: -0 === 0,\n  isNaN: Object.is(NaN, NaN),\n  strictNaN: NaN === NaN\n}\n', solution: 'return {\n  isMinusZero: Object.is(-0, 0),\n  strictMinusZero: -0 === 0,\n  isNaN: Object.is(NaN, NaN),\n  strictNaN: NaN === NaN\n}', tests: [{ input: [], expected: { isMinusZero: false, strictMinusZero: true, isNaN: true, strictNaN: false } }], hints: ["Object.is -0 aur 0 ko alag maanta hai", "Object.is NaN === NaN true deta hai"] },
  { id: "02-03-50", title: "Proxy revoke pattern", starterCode: 'let data = { name: "Hariom" }\nconst { proxy, revoke } = Proxy.revocable(data, {\n  get(target, prop) {\n    return target[prop]\n  }\n})\nconst name1 = proxy.name\nrevoke()\ntry {\n  const name2 = proxy.name\n} catch(e) {\n  return { name1, error: e.message }\n}\n', solution: 'let data = { name: "Hariom" }\nconst { proxy, revoke } = Proxy.revocable(data, {\n  get(target, prop) {\n    return target[prop]\n  }\n})\nconst name1 = proxy.name\nrevoke()\ntry {\n  const name2 = proxy.name\n} catch(e) {\n  return { name1, error: e.message }\n}', tests: [{ input: [], expected: { name1: "Hariom", error: "Cannot perform \'get\' on a proxy that has been revoked" } }], hints: ["Proxy.revocable se proxy revoke kar sakte ho", "Revoke ke baad proxy use nahi kar sakte"] },
])

